// ---- wire/audit_log.go ----

// TruncatedHeader names the response header an audit CSV export sets to
// the row cap when it stopped there (the gateway exposes it to
// cross-origin clients).
export const TruncatedHeader = "X-Bnbloc-Truncated";

// Audit log entry kinds written by the platform itself. Component kinds
// (core, plugin, notifier, auth-provider, webhook) are the extension kinds
// recorded by the component lifecycle and their deliveries.
export const AuditKindBorrow = "borrow";
export const AuditKindSession = "session";
export const AuditKindMember = "member";
export const AuditKindTenant = "tenant";
export const AuditKindAPIToken = "api-token";
export const AuditKindAdminAlert = "admin-alert";
// AuditKindPlatformAgent: the platform-agent policy saved (platform
// level) or a platform agent added to / removed from a room (the room's
// tenant).
export const AuditKindPlatformAgent = "platform-agent";
// AuditKindRetention: a data retention policy saved (platform default or
// a tenant override) or a retention pass deleting a tenant's expired
// data (docs/prd/2026-10-10-enterprise-scale.md §3).
export const AuditKindRetention = "retention";
// AuditKindContent: a content component used for a run (an expert a
// chat asked an agent to wear).
export const AuditKindContent = "content";
// AuditKindApp: an interactive app's data read out (name = the app):
// an owner's export, or an agent's read through its job's grant.
export const AuditKindApp = "app";
// AuditKindSchedule: a schedule an agent created or deleted for the person
// who asked it (name = the room; the detail says which, never its text).
export const AuditKindSchedule = "schedule";
// AuditKindAssist: an AI assist ran (name = task@version; the model,
// tokens and latency, never the text) or the assist model was set.
export const AuditKindAssist = "assist";

// AuditLogEntry is one normalized audit record. ID is unique across sources
// ("<source>:<row id>"). Name is the record's subject (component name, member
// id, token id, the borrowed agent's owner, ...). TenantID is empty for a
// platform-level record (only the platform view shows those).
export interface AuditLogEntry {
  id: string;
  source: string;
  kind: string;
  name: string;
  action: string;
  actor?: string;
  tenantId?: string;
  outcome?: string;
  detail?: string;
  roomId?: string;
  atMs: number;
}

// AuditLogReply is one page, newest first. NextCursor is opaque; absent at
// the end of the log.
export interface AuditLogReply {
  entries: AuditLogEntry[];
  nextCursor?: string;
}

// Audit outcomes: the one vocabulary of an audit record's outcome
// (internal/audit.Record writers; the web's auditOutcomeTone reads it).
export const AuditOutcomeOK = "ok";
export const AuditOutcomeAllow = "allow";
export const AuditOutcomeDeny = "deny";
export const AuditOutcomeDelivered = "delivered";
export const AuditOutcomeFailed = "failed";
export const AuditOutcomeQueued = "queued";
export const AuditOutcomeRunning = "running";
export const AuditOutcomeRevoked = "revoked";

// ---- wire/budgets.go ----

// UsageBudgetLimits is one budget as an admin sets it. At least one of Tokens
// / Cost is set; an absent one is no limit on that dimension.
export interface UsageBudgetLimits {
  tokens?: number;
  cost?: number;
  // WarnAtPercent (1..99, default 80) sends the first warning; reaching
  // 100% sends the second.
  warnAtPercent: number;
  // HardStop refuses the member's own agent drives (tenant budget: every
  // drive in the organization) once the budget is reached.
  hardStop: boolean;
}

// MemberBudgetLimits is a member budget in PUT /v1/tenant/budgets.
export interface MemberBudgetLimits extends UsageBudgetLimits {
  userId: string;
}

// TenantBudgetsUpdate is the body of PUT /v1/tenant/budgets: the whole budget
// set (an absent tenant budget or member is removed).
export interface TenantBudgetsUpdate {
  tenant: UsageBudgetLimits | null;
  members: MemberBudgetLimits[];
}

// UsageBurn is the usage measured against a budget in the period.
export interface UsageBurn {
  tokens: number;
  cost: number;
}

// BudgetView is one budget with its burn: Percent is the higher of the
// token and cost burn percentages (floored); Reached when either is at or
// over its limit.
export interface BudgetView extends UsageBudgetLimits {
  userId?: string;
  burn: UsageBurn;
  percent: number;
  reached: boolean;
  updatedBy?: string;
  updatedAtMs?: number;
}

// MemberBurn is one owner's burn in the period (budgeted or not).
export interface MemberBurn extends UsageBurn {
  userId: string;
}

// BudgetPeriod is the month a budget reply covers.
export interface BudgetPeriod {
  period: string; // "YYYY-MM" (UTC)
  periodStartMs: number;
  periodEndMs: number;
}

// TenantBudgetsReply is GET (and the answer to PUT) /v1/tenant/budgets.
export interface TenantBudgetsReply extends BudgetPeriod {
  tenant: BudgetView | null;
  members: BudgetView[];
  // Usage is every owner's burn this period, budgeted or not.
  usage: MemberBurn[];
}

// MyBudgetReply is GET /v1/my/budget: the caller's own budget (nil when none)
// and burn, and whether their agents are stopped by a hard stop.
export interface MyBudgetReply extends BudgetPeriod {
  budget: BudgetView | null;
  burn: UsageBurn;
  // Blocked is true when a hard-stop budget is reached; BlockedBy names it
  // ("member" = the caller's own, "tenant" = the organization's).
  blocked: boolean;
  blockedBy?: string;
}

// ---- wire/client_config.go ----

// ClientConfig is GET /v1/public/client-config: the deployment facts a client
// needs before it signs in. SitesOrigin is the separate origin serving
// every site and its app API (BNBLOC_SITES_ORIGIN, e.g.
// https://sites.bnbloc.example.com), empty when sites are served from the
// gateway's own origin; the desktop shell's site scheme forwards there.
export interface ClientConfig {
  sitesOrigin?: string;
}

// ---- wire/component_shapes.go ----

// ComponentEndpoint is part of a component package (core/pkgmeta).
export interface ComponentEndpoint {
  baseUrl: string;
}

// ComponentArtifact is part of a component package (core/pkgmeta).
export interface ComponentArtifact {
  url: string;
  sha256: string;
}

// ComponentPermissions is part of a component package (core/pkgmeta).
export interface ComponentPermissions {
  network?: string[];
  // Host lists the desktop plugin host API capabilities a plugin sidecar
  // may use (plugin packages only; PluginHostPermissions is the registry).
  // A plugin declaring any gets BNBLOC_PLUGIN_HOST_URL/_TOKEN at launch.
  host?: string[];
}

// ComponentLocalSetting is one field of a plugin's desktop-local settings schema.
// Secret values are write-only in the desktop UI (masked, never shown back).
export interface ComponentLocalSetting {
  key: string;
  label: string;
  help?: string;
  secret?: boolean;
  required?: boolean;
}

// ComponentSidecar is part of a component package (core/pkgmeta).
export interface ComponentSidecar {
  listenEnv?: string;
  // SupervisedEnv names the env var the desktop sets to "1" at launch so the
  // sidecar knows it is supervised and exits when its stdin pipe closes.
  supervisedEnv?: string;
  localUrl: string;
  args?: string[];
  // TokenEnv names the env var the desktop sets to a fresh random bearer
  // token at every launch. A sidecar declaring it must require that bearer
  // on every request; the desktop hands the same token to its local callers.
  tokenEnv?: string;
  // DataDirEnv names the env var the desktop sets to a per-component
  // private data directory it creates (owner-only) before launch.
  dataDirEnv?: string;
  // MountsEnv names the env var the desktop sets to the descriptor file a
  // plugin with the "sandbox-mounts" capability writes its read-only sandbox
  // mounts to (docs/architecture/sandbox-mounts.md); MountRootEnv the folder
  // the host side of those mounts must be under. Both only with that
  // capability.
  mountsEnv?: string;
  mountRootEnv?: string;
  // Files are extra per-platform artifacts the sidecar needs beside its
  // executable (e.g. a VMM helper binary and a firmware library). Each is
  // published in Package.Artifacts under "<platform>/<name>", downloaded
  // and sha256-verified by the desktop exactly like the executable, and its
  // local path is handed to the sidecar in env Env.
  files?: ComponentSidecarFile[];
}

// ComponentSidecarFile declares one extra sidecar artifact (ComponentSidecar.Files).
export interface ComponentSidecarFile {
  name: string;
  env: string;
  // Executable marks a file the desktop must mark executable (+x).
  executable?: boolean;
}

// ComponentGuest is a sandbox package's machine profile (pkgmeta.Package.Guest).
export interface ComponentGuest {
  // Image is the OCI reference the machine boots (never a host path).
  image: string;
  cpus?: number;
  memoryMiB?: number;
}

// ComponentPreviewer is a previewer package's payload (pkgmeta.Package.Previewer).
export interface ComponentPreviewer {
  // Entry is the bundle-relative HTML document the frame loads.
  entry: string;
  match: FileMatch;
  // Rank orders previewers matching a file with equal specificity, like
  // the web registry's built-ins (lower first).
  rank: number;
  capabilities?: string[];
  toolbar?: ComponentPreviewerToolbarItem[];
}

// FileMatch declares the files something applies to: the files a
// previewer renders, the files a prompt-pack prompt is for. One validator:
// internal/filematch.
export interface FileMatch {
  mimeTypes?: string[];
  extensions?: string[];
}

// ComponentPreviewerToolbarItem is one declared toolbar control; the host renders it
// with its own icon for Icon (a code-owned name).
export interface ComponentPreviewerToolbarItem {
  id: string;
  icon: string;
  label: string;
  kind: string;
}

// ComponentMCP is an MCP component's payload (pkgmeta.Package.MCP).
export interface ComponentMCP {
  // Tools are the tools the server offers, for display (the server's own
  // tools/list stays authoritative at run time).
  tools: ComponentMCPTool[];
  // Env are the variables the server needs; values never ship in a
  // package (Credentials says where they come from).
  env?: ComponentMCPEnv[];
  // Credentials is member, org or bridge; required exactly when Env is
  // declared.
  credentials?: string;
  stdio?: ComponentMCPStdio;
  http?: ComponentMCPHTTP;
}

// ComponentMCPTool is one tool of the server.
export interface ComponentMCPTool {
  name: string;
  description?: string;
}

// ComponentMCPEnv is one variable an MCP server needs.
export interface ComponentMCPEnv {
  name: string;
  description?: string;
  secret?: boolean;
  required?: boolean;
}

// ComponentMCPStdio is how a stdio server is started: the materialized binary with
// these arguments (env values arrive as its process environment).
export interface ComponentMCPStdio {
  args?: string[];
}

// ComponentMCPHTTP is how an endpoint server is called.
export interface ComponentMCPHTTP {
  auth: ComponentMCPHTTPAuth;
}

// ComponentMCPHTTPAuth is the header an endpoint server expects: none, a bearer token
// (Authorization: Bearer <Env>), a named header (<Header>: <Env>), or a
// member's OAuth sign-in (Authorization: Bearer <their access token>).
export interface ComponentMCPHTTPAuth {
  scheme: string;
  header?: string;
  env?: string;
  // ClientID (oauth, optional) is a client the publisher registered with
  // the server's authorization server; without it the desktop registers
  // itself where the authorization server allows it.
  clientId?: string;
  // Scopes (oauth, optional) are requested when the server's challenge
  // names none.
  scopes?: string[];
}

// ---- wire/components.go ----

// ComponentProtocolRange is the Core Protocol range a core or sandbox
// package was published for (core/protocol.ProtocolRange).
export interface ComponentProtocolRange {
  min: string;
  max: string;
}

// ComponentTrust is how an installed component was verified: the publisher
// key that signed it and the hash of the package it installed.
export interface ComponentTrust {
  keyId?: string;
  contentHash?: string;
  signed: boolean;
}

// ComponentAdoption counts the members who opted in to a component.
export interface ComponentAdoption {
  memberInstalls: number;
  totalMembers?: number;
}

// PlatformComponent is one installed component in the platform console
// (GET /v1/platform/components).
export interface PlatformComponent {
  kind: string;
  name: string;
  version: string;
  publisher: string;
  runtime: ComponentRuntime;
  contract?: string;
  protocol: ComponentProtocolRange;
  keyId: string;
  contentHash: string;
  installedAtMs: number;
  description?: string;
  capabilities?: string[];
  permissions: ComponentPermissions;
  hooks?: string[];
  localSettings?: ComponentLocalSetting[];
  artifacts?: Record<string, ComponentArtifact>;
  endpoint?: ComponentEndpoint;
  sidecar?: ComponentSidecar;
  // RequiresDesktop marks a component that runs on each member's desktop
  // (a sidecar other than an auth provider, a stdio MCP server).
  requiresDesktop?: boolean;
  // Manifest is a manifest core's interpreted manifest
  // (core/manifestcore.Manifest), shown as published.
  manifest?: unknown;
  previewer?: ComponentPreviewer;
  mcp?: ComponentMCP;
  rollout: ComponentRollout;
  trust: ComponentTrust;
  adoption: ComponentAdoption;
}

// PlatformComponentsReply is GET /v1/platform/components.
export interface PlatformComponentsReply {
  components: PlatformComponent[];
}

// PublishedComponent answers an install: the installed component, and a
// notifier's signing secret on its first install (shown this once).
export interface PublishedComponent extends PlatformComponent {
  secret?: string;
}

// ComponentInstallRequest is POST /v1/platform/components: a package and
// its detached signature, as text.
export interface ComponentInstallRequest {
  package: string;
  signature: string;
  rollout?: ComponentRollout;
}

// ComponentRolloutRequest sets an installed component's rollout.
export interface ComponentRolloutRequest {
  rollout: ComponentRollout;
}

// MemberComponent is one component of the member catalog (GET
// /v1/components): what the member may use, and, once installed for them,
// what their desktop needs to run it.
export interface MemberComponent {
  kind: string;
  name: string;
  version: string;
  publisher?: string;
  description?: string;
  runtime?: ComponentRuntime;
  contract?: string;
  requiresDesktop?: boolean;
  hooks?: string[];
  // Permissions and LocalSettings tell the member's desktop how to launch
  // a plugin sidecar: the host API capabilities it may use, and the
  // settings the member fills in locally (never sent back here).
  permissions?: ComponentPermissions;
  localSettings?: ComponentLocalSetting[];
  artifacts?: Record<string, ComponentArtifact>;
  endpoint?: ComponentEndpoint;
  sidecar?: ComponentSidecar;
  // Capabilities and Protocol tell the desktop/bridge what a protocol
  // component (a sandbox runtime) was published to support before it is
  // launched; the running implementation's discovery stays authoritative.
  capabilities?: string[];
  protocol?: ComponentProtocolRange;
  rollout: ComponentRollout;
  installed: boolean;
  managed: boolean;
  installedAtMs?: number;
  // PublishedAtMs is when the platform installed this version.
  publishedAtMs?: number;
  // MemberInstalls counts the members who opted in (the platform list's
  // adoption.memberInstalls).
  memberInstalls?: number;
  // Guest is a sandbox's machine profile: the desktop prewarms it.
  guest?: ComponentGuest;
  // Previewer is an installed previewer's match/toolbar metadata, its
  // pinned bundle, and the caller's browser frame URL.
  previewer?: MemberComponentPreviewer;
  // MCP is an MCP tool's tools, env and credentials source.
  mcp?: MemberComponentMCP;
}

// MemberComponentPreviewer is an installed previewer in the member catalog:
// its package payload, its pinned bundle and the caller's frame.
export interface MemberComponentPreviewer extends ComponentPreviewer {
  // BundleURL is the gateway artifact URL of the archive (the desktop
  // downloads it and checks BundleSHA256).
  bundleUrl: string;
  bundleSha256: string;
  // FrameURL is the gateway-relative browser frame base (ticket included);
  // the host appends Entry.
  frameUrl: string;
  frameExpiresAtMs: number;
}

// MemberComponentMCP is an installed MCP tool in the member catalog: its
// package payload, how it is reached, and (org credentials) whether the
// member's organization configured its connector.
export interface MemberComponentMCP extends ComponentMCP {
  transport: string;
  // OrgConfigured is set for org credentials.
  orgConfigured?: boolean;
}

// ComponentsReply is GET /v1/components: the executable catalog the desktop
// supervises and the content components (experts, skill packs) the member
// may use.
export interface ComponentsReply {
  components: MemberComponent[];
  contentComponents: ContentComponent[];
}

// ComponentKey is one trusted publisher key (GET /v1/platform/component-keys).
export interface ComponentKey {
  keyId: string;
  publicKey: string;
  label?: string;
  addedAtMs?: number;
  addedBy?: string;
}

// ComponentKeysReply lists the trusted publisher keys, and whether this
// gateway refuses unsigned packages (the publishing UI demands a signature
// exactly when the install would).
export interface ComponentKeysReply {
  keys: ComponentKey[];
  signatureRequired: boolean;
}

// ---- wire/content_components.go ----

// ContentComponent is one content component as a member sees it, at its
// latest version (or the version a detail names).
export interface ContentComponent {
  id: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  description?: string;
  category?: string;
  tags?: string[];
  icon?: string;
  owner: string;
  scope: string;
  status: string;
  latestVersion: string;
  // Version is the version the rest of the fields describe (the latest
  // in a listing).
  version: string;
  // Permissions are the declared permissions (scripts, mcp.stdio,
  // mcp.http:<host>); NeedsSandbox is true when they force a sandboxed
  // drive for anyone but the author.
  permissions: string[];
  needsSandbox?: boolean;
  requires: ContentRequires;
  skills?: ContentSkill[];
  quickPrompts?: ContentQuickPrompt[];
  welcome?: string;
  // Prompts are a prompt pack's prompts (content_prompts.go).
  prompts?: ContentPrompt[];
  // Assist is an assist's task (docs/prd/2026-10-13-ai-assist.md §3).
  assist?: AssistSpec;
  // Mine is true for the caller's own personal component: they author it
  // (new versions, sharing, publishing).
  mine: boolean;
  // Removable is true when the caller may delete it: their own personal
  // component or a shared copy they hold.
  removable: boolean;
  // SharedBy is the author of a shared copy (Owner is its holder).
  sharedBy?: string;
  // SourceID is the author's component a shared copy or an org
  // publication was made from.
  sourceId?: string;
  // SourceLatestVersion is, on a shared copy, the author's latest version
  // when it is newer than the copy's ("update to the author's latest").
  sourceLatestVersion?: string;
  // Publication is, on the caller's own personal component, its
  // organization publication and latest publish request.
  publication?: ContentPublication;
  // Acked is true when the caller confirmed this version's declared
  // permissions (always true for content they authored and for one that
  // declares none).
  acked: boolean;
  // Uses counts the members and rooms that enabled or pinned it.
  uses: number;
  // Runs counts the agent runs that wore an expert and Members their
  // distinct requesters; for a pack, Members counts the members who
  // turned it on for themselves. Each is capped (store.MaxUsageCount).
  runs: number;
  members: number;
  // Favorite is true when the caller starred it; FavoriteCount counts
  // the members of the caller's organization who did (capped like the
  // usage counts).
  favorite: boolean;
  favoriteCount: number;
  // CoverURL is a work's cover image at this version
  // (GET /v1/content-components/{id}/versions/{v}/cover; the session
  // authorizes it; 404 when the work has none, and the card draws the
  // generated cover). Absent for the other kinds.
  coverUrl?: string;
  // WorkType is a work's type at this version (what deliverable it
  // snapshots); WorkFile its one file (absent for a site or an app).
  workType?: WorkType;
  workFile?: string;
  // Recipe is how a work was made (its manifest's), absent when it
  // carries none.
  recipe?: WorkRecipe;
  // Team is a team expert's roster (as its manifest names it).
  team?: ContentTeam;
  createdAtMs: number;
  updatedAtMs: number;
}

// ContentRequires mirrors a manifest's requires.
export interface ContentRequires {
  skills?: string[];
  prompts?: string[];
  mcp?: ContentMCPRequirement[];
  permissions?: string[];
}

// ContentSkill is one skill of a package.
export interface ContentSkill {
  name: string;
  description: string;
}

// ContentQuickPrompt is one expert quick prompt: its text, or Ref
// ("pack/prompt-id") to a prompt of a pack the expert requires, Resolved
// for the viewer when they may use such a pack (nil: the pack is missing).
export interface ContentQuickPrompt {
  title: string;
  prompt: string;
  ref?: string;
  resolved?: ContentPromptRef;
}

// ContentVersion is one immutable version.
export interface ContentVersion {
  version: string;
  sha256: string;
  bundleKey: string;
  // BundleURL is the download path of the bundle (GET /v1/artifacts/…).
  bundleUrl: string;
  sizeBytes: number;
  createdBy: string;
  createdAtMs: number;
}

// ContentComponentDetail answers GET /v1/content-components/{id}.
export interface ContentComponentDetail {
  component: ContentComponent;
  versions: ContentVersion[];
  // Resubmitted is the publish request a new version opened by itself:
  // the organization uses the component (or a request was pending), so
  // the new version waits for an org admin's approval while members keep
  // the approved one ("Gap closure" 5).
  resubmitted?: ContentPublishRequest;
  // OrgPublished is the version a new save published to the
  // organization at once: it uses the component and requires no
  // approval (contentshare.NeedsApproval).
  orgPublished?: string;
}

// ContentFile is one file of a version: its text when it is UTF-8 and
// small enough to view.
export interface ContentFile {
  path: string;
  sizeBytes: number;
  text?: string;
  binary?: boolean;
}

// ContentVersionDetail answers GET /v1/content-components/{id}/versions/{v}:
// the component as of that version, its instructions (an expert) and its
// files, and each skill's body for the Library form.
export interface ContentVersionDetail {
  component: ContentComponent;
  version: ContentVersion;
  instructions?: string;
  skillBodies?: Record<string, string>;
  files: ContentFile[];
}

// Content use scopes (ContentUse.Scope).
export const ContentUseMember = "member";
export const ContentUseRoom = "room";
// ContentUseRoomExpert is a room's expert: one of its pinned experts
// every agent turn in the room wears (scope id = the room).
export const ContentUseRoomExpert = "room-expert";

// ContentUse is where a component is enabled (a member's skill packs, a
// room's skill packs) or pinned (a room's experts).
export interface ContentUse {
  scope: ContentUseScope;
  scopeId: string;
  componentId: string;
  kind: ContentKind;
  pinnedVersion?: string;
  createdBy: string;
  createdAtMs: number;
  component?: ContentComponent;
  // UpdateAvailable is true when a pinned version is behind the latest.
  updateAvailable?: boolean;
}

// ContentUsesReply answers GET /v1/content-uses?room=: the caller's member
// uses and, with a room, the room's.
export interface ContentUsesReply {
  member: ContentUse[];
  room?: ContentUse[];
  // RoomExpert is the id of the room's expert (one of its pinned
  // experts), when it has one.
  roomExpert?: string;
}

// ContentUseRequest is PUT /v1/content-uses.
export interface ContentUseRequest {
  scope: string;
  roomId?: string;
  componentId: string;
  // Version pins a version; empty follows the latest.
  version?: string;
}

// ChatExpert is the expert a chat asks its agent to wear: a component id
// and an optional version (empty = the latest when the chat is posted;
// the job records the version actually used).
export interface ChatExpert {
  id: string;
  version?: string;
}

// Content sources of an effective package (ContentRef.Source).
export const ContentSourceExpert = "expert";
export const ContentSourceExpertNeeds = "expert-requires";
export const ContentSourceRoom = "room";
export const ContentSourceMember = "member";
export const ContentSourceRoomExpert = "room-expert";

// ContentRef is one resolved package in effect for a turn.
export interface ContentRef {
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  sha256: string;
  bundleKey: string;
  // Owner is the package's author (a shared copy's author, not its
  // holder; "" for platform content): content that is not the agent
  // owner's own and needs the sandbox forces a sandboxed drive.
  owner: string;
  source: string;
  permissions?: string[];
  needsSandbox?: boolean;
  // MCP are the MCP tool components the package requires.
  mcp?: ContentMCPRequirement[];
}

// ContentEffective answers GET /v1/content-components/effective?job=&room=
// for the bridge driving the job: the expert the chat picked and the skill
// packs in effect (room, the agent owner's, the expert's requirements), and
// requirements no usable package satisfies.
export interface ContentEffective {
  expert?: ContentRef;
  // RoomExpert is the room's expert, worn under the chat's own (absent
  // when the room has none, or it is the chat's expert).
  roomExpert?: ContentRef;
  // Team is the chat expert's roster when it is a team, each member's
  // expert resolved as the requester.
  team?: ContentTeam;
  skillPacks: ContentRef[];
  // MCP are the MCP tool components the packages above require that the
  // requester may use (mcp_tools.go).
  mcp?: ContentMCPTool[];
  missing?: string[];
}

// Content scopes on the wire (ContentComponent.Scope, publish requests).
export const ContentScopePersonal = "personal";
export const ContentScopeShared = "shared";
export const ContentScopeOrg = "org";
export const ContentScopePlatform = "platform";

// ContentPublication is an author's view of their component's
// organization publication: the org copy members use (its version and
// status, absent until a first approval) and the latest publish request.
export interface ContentPublication {
  orgComponentId?: string;
  orgVersion?: string;
  orgStatus?: string;
  request?: ContentPublishRequest;
}

// ContentPublishRequest is a request to publish a version of an author's
// component to the organization (status pending, approved, declined or
// withdrawn).
export interface ContentPublishRequest {
  id: string;
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  requestedBy: string;
  note?: string;
  status: string;
  decidedBy?: string;
  decisionNote?: string;
  decidedAtMs?: number;
  createdAtMs: number;
  // ApprovedVersion is the version the organization uses now ("" before
  // a first approval).
  approvedVersion?: string;
}

// ContentShareRequest is POST /v1/content-components/{id}/shares: named
// members of the author's organization and/or a room (its human members),
