// notification.
export interface ContentShareRequest {
  members?: string[];
  roomId?: string;
  version?: string;
  note?: string;
}

// ContentShareReply answers a share: per recipient, the copy and whether it
// was created, moved to the version (updated) or already had it
// (unchanged); recipients skipped with the reason.
export interface ContentShareReply {
  version: string;
  shared: ContentShareResult[];
  skipped: ContentShareSkip[];
  // Room is the room whose share now stands: members who join it later
  // get a copy too, until the author revokes it.
  room?: string;
}

// Share outcomes (ContentShareResult.Status).
export const ContentShareCreated = "created";
export const ContentShareUpdated = "updated";
export const ContentShareUnchanged = "unchanged";

// ContentShareResult is one recipient's copy.
export interface ContentShareResult {
  member: string;
  componentId: string;
  version: string;
  status: string;
}

// ContentShareSkip is a recipient a share did not reach.
export interface ContentShareSkip {
  member: string;
  reason: string;
}

// ContentShares answers GET /v1/content-components/{id}/shares: the
// copies made from the author's component and its standing room shares.
export interface ContentShares {
  copies: ContentCopy[];
  rooms: ContentRoomShare[];
}

// ContentRoomShare is a standing share with a room: members who join the
// room get a copy at Version until the author revokes it
// (DELETE /v1/content-components/{id}/shares/rooms/{room}).
export interface ContentRoomShare {
  roomId: string;
  version: string;
  note?: string;
  createdAtMs: number;
  updatedAtMs: number;
}

// ContentCopy is one shared copy of an author's component
// (GET /v1/content-components/{id}/shares).
export interface ContentCopy {
  member: string;
  componentId: string;
  version: string;
  updatedAtMs: number;
}

// ContentPublishInput is POST /v1/content-components/{id}/publish: scope
// "org" opens a publish request for Version (default: the latest);
// "personal" withdraws a pending request and takes the component out of
// the organization; "platform" is refused with what a platform admin does.
export interface ContentPublishInput {
  scope: string;
  version?: string;
  note?: string;
}

// ContentPublishReply answers a publish: the scope now in effect and the
// request it opened (org).
export interface ContentPublishReply {
  scope: string;
  request?: ContentPublishRequest;
  note: string;
}

// ContentDecisionInput approves or declines a publish request.
export interface ContentDecisionInput {
  note?: string;
}

// ContentReview is GET /v1/tenant/content-requests/{id}: what an org admin
// reviews before approving. Component is the requested version (declared
// permissions, requirements with MCP tools, a team's roster, skills);
// ScriptFiles are the files that execute; Previous is the version the
// organization uses now (nil for a first publication) and Files the
// changes from it, file by file (every file is "added" for a first one).
export interface ContentReview {
  request: ContentPublishRequest;
  component: ContentComponent;
  scriptFiles: string[];
  previous?: ContentComponent;
  files: ContentFileChange[];
}

// File changes of a review (ContentFileChange.Change).
export const ContentFileAdded = "added";
export const ContentFileRemoved = "removed";
export const ContentFileChanged = "changed";

// ContentFileChange is one file that differs between two versions: its
// text before and after (bounded; Truncated when a side was cut), or
// Binary.
export interface ContentFileChange {
  path: string;
  change: string;
  binary?: boolean;
  before?: string;
  after?: string;
  truncated?: boolean;
}

// ContentAdminComponent is an organization's or the platform's published
// component as an admin manages it: the component (any status) and its
// author.
export interface ContentAdminComponent {
  component: ContentComponent;
  tenantId?: string;
  // EnabledTenants limits platform content to these organizations
  // (absent = every organization); set with
  // PUT /v1/platform/components/{name}/tenants?kind=.
  enabledTenants?: string[];
}

// ---- wire/content_drafts.go ----

// ContentDraft answers POST /v1/content-drafts?job=&room= (the room tools'
// try_draft): a staged, unsaved expert or skill pack that a job the staging
// job dispatches may wear until ExpiresAtMs. It is never listed in a
// Library. Dispatch it with DispatchRequest.Draft = ID.
export interface ContentDraft {
  id: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  expiresAtMs: number;
}

// ---- wire/content_events.go ----

// EventContentUsesChanged is a transient room event: a room's content uses
// (pinned experts, the room expert, room skill and prompt packs) changed.
// Clients refetch GET /v1/content-uses?room= on it, so the composer and the
// room settings follow without reopening the room. Payload:
// ContentUsesChanged.
export const EventContentUsesChanged = "content_uses_changed";

// ContentUsesChanged is the payload of EventContentUsesChanged.
export interface ContentUsesChanged {
  scope: string;
  componentId: string;
}

// EventContentSaved is a transient room event: the room tools saved a
// content component (save_component) or asked to publish one
// (publish_component) for the job's requester, in the job's room. The
// workshop shows the save from it ("Saved expert …" with "Open in Library"
// and "Try it now") instead of re-listing the Library after every agent
// reply. Payload: ContentSaved; clients act only on their own (Owner).
export const EventContentSaved = "content_saved";

// ContentSaved actions: a save, a publish request to the organization, or
// a publication to it that took effect at once (the organization requires
// no approval).
export const ContentSavedSaved = "saved";
export const ContentSavedSubmitted = "submitted";
export const ContentSavedPublished = "published";

// ContentSaved is the payload of EventContentSaved.
export interface ContentSaved {
  componentId: string;
  kind: ContentKind;
  name: string;
  displayName?: string;
  version: string;
  // Action is saved (a new component or version), submitted (a publish
  // request to the organization, opened by publish_component or by the
  // save of a new version of a component the organization uses) or
  // published (the same, where the organization requires no approval).
  action: ContentSavedAction;
  // Created marks a new component (not a new version).
  created?: boolean;
  // Owner is the member it was saved for (the job's requester).
  owner: string;
}

// ---- wire/content_prompts.go ----

// ContentPrompt is one prompt of a prompt pack. Body holds {{name}}
// placeholders, each one of Variables.
export interface ContentPrompt {
  id: string;
  title: string;
  body: string;
  variables?: ContentPromptVariable[];
  tags?: string[];
  // Slash is the composer command that inserts it ("/release-notes").
  slash?: string;
  // Starter offers it among the starter prompts of a room the pack is
  // turned on for.
  starter?: boolean;
  // Files scopes it to matching files: a starter with files is a file
  // suggestion, not a room starter.
  files?: FileMatch;
  // Selection scopes it to selections of these kinds (a selection
  // suggestion).
  selection?: string[];
  // Uses counts its insertions by every member.
  uses: number;
}

// ContentPromptVariable is one {{name}} of a prompt: a text field, or a
// select of Options.
export interface ContentPromptVariable {
  name: string;
  label?: string;
  default?: string;
  options?: string[];
}

// ContentPromptRef is a pack's prompt an expert quick prompt resolved to:
// the pack (component id, name, version in effect) and the prompt.
export interface ContentPromptRef {
  componentId: string;
  pack: string;
  version: string;
  prompt: ContentPrompt;
}

// SavePromptRequest is POST /v1/content-components/prompts: a prompt saved
// into the caller's personal prompt pack (created on the first save).
export interface SavePromptRequest {
  title?: string;
  body: string;
  tags?: string[];
}

// SavePromptReply answers it: the pack at its new version and the saved
// prompt's id.
export interface SavePromptReply {
  component: ContentComponent;
  promptId: string;
  // Created is true when this save created the pack.
  created: boolean;
}

// ---- wire/cores.go ----

// AgentTarget is one agent a core can drive for the caller
// (GET /v1/local-agent/targets). ID is core-qualified ("<core>/<rawid>",
// core.QualifyTargetID); Core names the core for grouping. The model and
// reasoning pickers are what the core discovered (absent: no picker).
export interface AgentTarget extends AgentModelOptions {
  id: string;
  provider: string;
  core: string;
}

// AgentTargetsReply is GET /v1/local-agent/targets.
export interface AgentTargetsReply {
  targets: AgentTarget[];
}

// Core is one registered core as GET /v1/cores lists it to a member (the
// rollout gate applied). Available means the gateway resolved an endpoint
// for it; Runtime "sidecar" cores are driven by the member's own bridge.
export interface Core {
  name: string;
  available: boolean;
  backend: string;
  runtime?: string;
  requiresDesktop?: boolean;
  rollout?: string;
}

// CoresReply is GET /v1/cores.
export interface CoresReply {
  cores: Core[];
}

// ---- wire/decisions.go ----

// Decision question types.
// DecisionPredicate: a yes/no question; the answer is the probability
// of yes.
export const DecisionPredicate = "predicate";
// DecisionChoice: one of Choices; the answer is the choice, its
// confidence and a probability per choice.
export const DecisionChoice = "choice";
// DecisionScore: a level of Levels (lowest first); the answer is a level
// index (fractional), its confidence and a probability per level.
export const DecisionScore = "score";

// DecisionRefusal is an answer's type when the model declined that one
// question (its other answers stand).
export const DecisionRefusal = "refusal";

// Decision bounds (the provider's own, so a refusal is ours and says why).
export const MaxDecisionQuestions = 128;
export const MaxDecisionChoices = 255;
export const MaxDecisionLevels = 10;
export const MaxDecisionInputText = 65536;
export const MaxDecisionImages = 8;
export const MaxDecisionImageBytes = 4194304;
export const MaxDecisionInstructions = 4096;
export const MaxDecisionLabel = 512;
export const MaxDecisionDescription = 2048;

// DecisionRequest is POST /v1/decisions: Input (Text, or Messages) and the
// questions. Answers come back in question order.
export interface DecisionRequest {
  // Model is one of the provider's models (the first is the default; an
  // unknown name falls back to it).
  model?: string;
  // Input is the thing to judge: a JSON string, or a list of
  // DecisionMessage (user messages whose parts are input_text /
  // input_image, a data URL). internal/decision.ParseInput reads it.
  input: unknown;
  // Questions are 1…MaxDecisionQuestions questions; names, when set, are
  // unique and come back in the answers.
  questions: DecisionQuestion[];
}

// DecisionMessage is one user message of an input.
export interface DecisionMessage {
  role: string;
  content: DecisionPart[];
}

// DecisionPart is one part of a message: input_text (Text) or input_image
// (ImageURL, a data URL of a PNG, JPEG, WebP or GIF image).
export interface DecisionPart {
  type: string;
  text?: string;
  image_url?: string;
}

// DecisionQuestion is one question.
export interface DecisionQuestion {
  type: DecisionQuestionType;
  name?: string;
  instructions: string;
  // Choices, for a choice question: 2…MaxDecisionChoices values.
  choices?: DecisionChoiceOption[];
  // Levels, for a score question: 2…MaxDecisionLevels, lowest first.
  levels?: DecisionLevel[];
}

// DecisionChoiceOption is one value a choice question may answer.
export interface DecisionChoiceOption {
  value: string;
  description?: string;
}

// DecisionLevel is one level of a score question.
export interface DecisionLevel {
  label: string;
  description?: string;
}

// DecisionReply is POST /v1/decisions' answer: one answer per question, in
// question order, and the provider's usage.
export interface DecisionReply {
  // Model is the model the provider says answered.
  model: string;
  answers: DecisionAnswer[];
  usage: DecisionUsage;
}

// DecisionAnswer is one question's answer: its question's type, or
// DecisionRefusal. Probability is a predicate's (the probability of yes);
// Choice a choice's; Score a score's (a level index, possibly fractional).
// Probabilities is per choice value or per level, Confidence the model's
// for the choice or the score.
export interface DecisionAnswer {
  type: string;
  name?: string;
  probability?: number;
  choice?: string;
  score?: number;
  confidence?: number;
  probabilities?: DecisionProbability[];
}

// DecisionProbability is the probability of one choice value (Value, a
// string) or one level (Value, its index, and Label).
export interface DecisionProbability {
  value: unknown;
  label?: string;
  probability: number;
}

// DecisionUsage is the provider's token count for the call (the upstream
// formats' own field names).
export interface DecisionUsage {
  input_tokens: number;
  output_tokens: number;
}

// SystemOneRequest is POST /v1/systemone: State is the thing to judge (a
// string, or any JSON value, judged as its JSON text); Questions is a map
// of question name to SystemOneQuestion, read in its written order
// (internal/decision.FromSystemOne).
export interface SystemOneRequest {
  model?: string;
  state: unknown;
  questions: unknown;
}

// SystemOne question types: SystemOneNoul is the yes/no question (a
// DecisionPredicate); choice and score are named as in the list format.
export const SystemOneNoul = "noul";

// SystemOneReply is POST /v1/systemone's answer: one answer per question,
// keyed by its name.
export interface SystemOneReply {
  model: string;
  answers: Record<string, SystemOneAnswer>;
  usage: DecisionUsage;
}

// SystemOneAnswer is one answer: noul (Noul, the probability of yes),
// choice (Choice, Confidence, Probabilities per label), score (Score,
// Confidence, Legend and Probabilities per level index), or refusal.
export interface SystemOneAnswer {
  type: string;
  noul?: number;
  choice?: string;
  score?: number;
  confidence?: number;
  legend?: Record<string, string>;
  probabilities?: Record<string, number>;
}

// DecisionCapability is GET /v1/decisions: whether decisions run for the
// caller, and the models they may pick from (the first the default).
export interface DecisionCapability {
  available: boolean;
  models?: string[];
}

// ---- wire/dispatch.go ----

// Dispatch guard limits. They are protocol safety constants, not deployment
// data: they bound how far one person's message can fan out through agents
// (at most MaxDispatchFanOut^MaxDispatchDepth jobs), the same for every
// deployment, and the room-tools contract documents them to agents.
// MaxDispatchDepth is the deepest hop a dispatched job may sit at: a
// person's message starts depth 0, each dispatch adds one.
export const MaxDispatchDepth = 3;
// MaxDispatchFanOut is how many jobs one parent job may dispatch
// (persisted dispatches, whatever their outcome).
export const MaxDispatchFanOut = 8;

// DispatchMarker is payload.dispatchedBy on a chat_message an agent
// dispatched: the parent job and its request, the new job's depth and the
// dispatching agent's handle ("jack/codex"). Clients render "maya → via
// jack/codex → bob/claude". An expert the dispatch asked the target to wear is the
// message's ordinary payload.expert.
export interface DispatchMarker {
  jobId: string;
  // ParentSeq is the room sequence of the parent job's request: clients
  // nest the dispatch (and, through its replies' sourceSeq, everything it
  // produced) under that message without looking jobs up.
  parentSeq?: number;
  depth: number;
  via?: string;
  // Role is the team role the dispatch staffs (a team lead's dispatch).
  role?: string;
}

// DispatchRecipient names the agent a dispatch addresses, in the chat
// recipient's shape.
export interface DispatchRecipient {
  ownerId: string;
  provider: string;
  core?: string;
}

// DispatchRequest is the body of POST /v1/rooms/{roomId}/dispatch (and of
// realtime's POST /internal/v1/rooms/{roomId}/dispatch). Expert asks the
// target to wear an expert exactly as a typed chat does (it must be usable
// by the requester, who authors the post). ClientMsgID makes a retried
// dispatch idempotent.
export interface DispatchRequest {
  parentJobId: string;
  recipient: DispatchRecipient;
  text: string;
  expert?: ChatExpert;
  clientMsgId?: string;
  // Role names the team role the dispatch staffs ([a-z0-9-]); the feed
  // labels the dispatch with it.
  role?: string;
  // Draft asks the target to wear a staged draft (ContentDraft.ID, the
  // room tools' try_draft) instead of an Expert: admitted only for a
  // draft the parent job staged in this room, before it expires.
  draft?: string;
}

// DispatchReply answers an accepted dispatch: the posted message's room
// sequence (deliverables link back to it as sourceSeq) and the new job.
export interface DispatchReply {
  sequence: number;
  jobId: string;
  depth: number;
}

// Dispatch refusal codes: the JSON body of a refused dispatch is
// {"code": <code>, "error": <message>}.
export const DispatchParentNotFound = "parent_not_found";
export const DispatchParentNotRunning = "parent_not_running";
export const DispatchNotParentBridge = "not_parent_bridge";
export const DispatchRequesterGone = "requester_not_member";
export const DispatchDepthExceeded = "depth_exceeded";
export const DispatchFanOutExceeded = "fan_out_exceeded";
export const DispatchSelf = "self_dispatch";
export const DispatchCycle = "dispatch_cycle";
export const DispatchPeopleChat = "people_chat";
export const DispatchExpertUnusable = "expert_not_available";
export const DispatchDraftUnavailable = "draft_not_available";
export const DispatchInvalid = "invalid_dispatch";

// AgentRunDispatch is a run's dispatch origin: the parent job and the hop
// depth (run records of jobs an agent dispatched).
export interface AgentRunDispatch {
  jobId: string;
  depth: number;
}

// ---- wire/event_kinds.go ----

// Room event kinds not declared beside their payloads.
// EventAgentJobCreated carries the queued AgentJob (realtime, PostChat).
export const EventAgentJobCreated = "agent_job_created";
// EventAgentJobUpdated carries the AgentJob after a status change
// (activity).
export const EventAgentJobUpdated = "agent_job_updated";
// EventAgentSessionState carries ReportSessionStateInput (activity): an
// agent session working or idle.
export const EventAgentSessionState = "agent_session_state";
// EventAgentRoster carries {"agents": [...]}: the agents members'
// bridges advertise in the room.
export const EventAgentRoster = "agent_roster";
// EventPresenceJoin / EventPresenceLeave carry {"userId"}; a
// EventPresenceSnapshot follows each with {"members": [...]}.
export const EventPresenceJoin = "presence_join";
export const EventPresenceLeave = "presence_leave";
export const EventPresenceSnapshot = "presence_snapshot";
// EventPresenceTyping carries {"userId"}, scoped to the channel typed in.
export const EventPresenceTyping = "presence_typing";
// EventMessageDeleted / EventMessageEdited carry the message's sequence
// (and the new text), scoped to its channel.
export const EventMessageDeleted = "message_deleted";
export const EventMessageEdited = "message_edited";
// EventArtifactUpdated announces a new artifact version (bnbloc-room).
export const EventArtifactUpdated = "artifact_updated";
// EventArtifactState relays an artifact's live collaboration state.
export const EventArtifactState = "artifact_state";

// EventKindSpec is one registered room event kind.
export interface EventKindSpec {
  // Name is the kind string (wire.Event.Kind).
  name: RoomEventKind;
  // Durable kinds take a per-room sequence and are persisted to the room
  // feed (room_messages): the only kinds history and a handoff package
  // hold. Every other kind is transient, with sequence 0.
  durable?: boolean;
  // Replay kinds are retained in the hub's replay buffer and delivered
  // again to a reconnecting stream. A transient kind is live only: a
  // replayed toast, badge, typing hint or stale state would look new to
  // the client.
  replay?: boolean;
  // Revocation kinds end access to the room (a member removed, the room
  // deleted): the affected streams close after delivering them, and they
  // are never replayed.
  revocation?: boolean;
  // ChannelScoped kinds carry the channelId of the message or channel they
  // concern; a single-channel stream receives them only for its channel.
  channelScoped?: boolean;
}

// RoomEventKinds is the registry of room event kinds. The web's
// RoomEventKind union (and RoomEventKindValues) is generated from the Name
// of each row: a kind registered here is a kind the web listens for.
export const RoomEventKinds: readonly EventKindSpec[] = [{ name: "chat_message", durable: true, replay: true, channelScoped: true }, { name: "agent_messages", durable: true, replay: true, channelScoped: true }, { name: "agent_job_created", channelScoped: true }, { name: "agent_job_updated", channelScoped: true }, { name: "agent_job_progress", channelScoped: true }, { name: "agent_session_state" }, { name: "agent_roster" }, { name: "presence_join" }, { name: "presence_leave" }, { name: "presence_snapshot" }, { name: "presence_typing", channelScoped: true }, { name: "message_deleted", channelScoped: true }, { name: "message_edited", channelScoped: true }, { name: "task_updated", channelScoped: true }, { name: "artifact_updated" }, { name: "artifact_state" }, { name: "member_joined" }, { name: "member_removed", revocation: true }, { name: "room_deleted", revocation: true }, { name: "content_saved" }, { name: "content_uses_changed" }, { name: "app_changed" }];

// ---- wire/handoff.go ----

// RoomExportFormat is the manifest "format" of the only package version this
// build writes and accepts. An import of any other value is refused.
export const RoomExportFormat = "bnbloc.room-export/v1";

// Room feed kinds. Only these two are durable history (RoomEventKinds:
// realtime persists them; presence/typing/state churn is transient), so they
// are the only kinds a handoff package carries.
export const KindChatMessage = "chat_message";
export const KindAgentMessages = "agent_messages";

// RoomExportManifest is manifest.json at the package root.
export interface RoomExportManifest {
  format: string;
  exportedAtMs: number;
  exportedBy: string;
  room: RoomExportRoom;
  // Channels lets an import recreate the room's message streams; messages
  // reference them by the original channel id.
  channels: RoomExportChannel[];
  // Members is informational only: an import never grants anyone access from
  // it, it only offers the list as invite suggestions.
  members: RoomExportMember[];
  agents: RoomExportAgent[];
  // AgentSessions is the platform's view of each agent session the feed
  // carries (ids + attribution + counts) — never core-internal state.
  agentSessions: RoomExportAgentSession[];
  messageCount: number;
  artifactCount: number;
  attachmentCount: number;
}

// RoomExportRoom describes the exported room.
export interface RoomExportRoom {
  id: string;
  name: string;
  topic?: string;
  createdAtMs: number;
}

// RoomExportChannel is one message stream of the exported room. Kind is
// RoomExportChannelPeople for the room's people chat (human-only, never
// visible to agents) and omitted for an ordinary channel; an import restores
// it as the new room's people chat.
export interface RoomExportChannel {
  id: string;
  name: string;
  isDefault: boolean;
  kind?: string;
}

// RoomExportChannelPeople marks the people chat in RoomExportChannel.Kind.
export const RoomExportChannelPeople = "people";

// RoomExportMember is one membership of the exported room.
export interface RoomExportMember {
  userId: string;
  role: string;
}

// RoomExportAgent is one agent that took part in the room, by its room handle
// (owner/provider) and, when the feed recorded it, the core that drove it.
export interface RoomExportAgent {
  owner: string;
  provider: string;
  core: string;
}

// RoomExportAgentSession is one agent session seen in the room feed.
export interface RoomExportAgentSession {
  agentSessionId: string;
  owner?: string;
  provider?: string;
  channelId?: string;
  messageCount: number;
  firstAtMs: number;
  lastAtMs: number;
}

// FeedMessage is one persisted room-feed entry: the room history row shape
// (sequence/kind/payload/atUnixMs/editedAtMs) plus the channel it belongs to.
// It is a messages.jsonl line, a page row of realtime's internal feed read,
// and a row of an import batch.
export interface FeedMessage {
  sequence: number;
  channelId?: string;
  kind: string;
  payload: unknown;
  atUnixMs: number;
  editedAtMs?: number;
}

// FeedPage is one ascending page of realtime's internal feed read.
export interface FeedPage {
  messages: FeedMessage[];
}

// RevisionsPage is GET /v1/rooms/{id}/history/revisions: the room's
// messages edited or deleted after a time, oldest revision first, and the
// room's newest revision time (0 = none). Agents' records follow the room
// with it.
export interface RevisionsPage {
  revisions: MessageRevision[];
  latestMs: number;
  // RetainedFrom is each listed channel's oldest stored message sequence
  // (channel id → seq): data retention purged everything before it, so
  // agents' records drop it too.
  retainedFrom?: Record<string, number>;
}

// MessageRevision is a message's last edit or deletion.
export interface MessageRevision {
  channelId: string;
  sequence: number;
  deleted?: boolean;
  atMs: number;
}

// ImportedMarker is stamped by realtime into payload.imported of every message
// written through the import path, so history readers (the web feed) can mark
// the row as imported. It is server-authored: no client send path can set it.
export interface ImportedMarker {
  fromRoomId: string;
  fromRoomName?: string;
  originalSequence: number;
  importedAtMs: number;
  // EditedAtMs carries the original edit stamp; imported rows are history
  // and cannot be edited again.
  editedAtMs?: number;
}

// Import batch bounds, shared by the room service (which chunks a package's
// messages) and realtime (which enforces them). They bound one internal
// request, not a package: a package is streamed as many batches.
export const MaxImportBatchBytes = 8388608;
export const MaxImportBatchMessages = 500;

// RoomImportBatch is the body of realtime's internal import write: history rows
// to persist (never publish) into the target room, in original order.
export interface RoomImportBatch {
  fromRoomId: string;
  fromRoomName?: string;
  importedAtMs: number;
  messages: FeedMessage[];
}

// RoomImportBatchReply reports how many rows were persisted and the last
// sequence assigned.
export interface RoomImportBatchReply {
  imported: number;
  lastSequence: number;
}

// RoomExportArtifact is artifacts/<artifactId>/artifact.json: the artifact's
// metadata plus every version's metadata and the package path of its content.
export interface RoomExportArtifact {
  artifactId: string;
  channelId?: string;
  kind: string;
  title: string;
  language?: string;
  mimeType?: string;
  fileName?: string;
  currentVersion: number;
  createdBy: string;
  createdAtMs: number;
  updatedAtMs: number;
  versions: RoomExportArtifactVersion[];
}

// RoomExportArtifactVersion is one immutable artifact revision. Storage
// "blob" marks a binary version: its file holds the raw bytes and
// ContentHash is their sha256 (inline text versions: "" or "inline").
// SourceJobID/SourceSeq are provenance in the SOURCE room only; an import
// does not carry them (jobs and sequences are not portable).
export interface RoomExportArtifactVersion {
  version: number;
  contentHash: string;
  storage?: string;
  mimeType?: string;
  sizeBytes?: number;
  sourceJobId?: string;
  sourceSeq?: number;
  summary?: string;
  authorUserId: string;
  createdAtMs: number;
  // File is the package path of this version's content.
  file: string;
}

// RoomExportAttachment is attachments/<attachmentId>/attachment.json.
export interface RoomExportAttachment {
  id: string;
  filename: string;
  contentType: string;
  size: number;
  sha256: string;
  // File is the package path of the attachment bytes.
  file: string;
}

// RoomHandoffInfo is a room's import provenance (GET /v1/rooms/{id}/handoff),
// present only for rooms created by an import.
export interface RoomHandoffInfo {
  roomId: string;
  sourceRoomId: string;
  sourceRoomName: string;
  sourceExportedAtMs: number;
  sourceExportedBy: string;
  importedBy: string;
  importedAtMs: number;
  suggestedMembers: RoomExportMember[];
}

// RoomImportResult answers POST /v1/rooms/import.
export interface RoomImportResult {
  roomId: string;
  name: string;
  importedMessages: number;
  importedArtifacts: number;
  importedAttachments: number;
  // SkippedAttachments lists attachment ids the upload path refused (e.g. a
  // type the current upload policy no longer accepts); their references are
  // dropped from the imported messages.
  skippedAttachments: string[];
  handoff: RoomHandoffInfo;
}

// ---- wire/job_notice.go ----

// JobNotice is one notice row about a job in the room feed: a line that says
// why nothing (or nothing more) came back — a refused or failed drive, a
// swept or budget-refused job, a team member that timed out, a lead's
// progress. It is a synthetic assistant row of an agent_messages batch whose
// payload carries `notice` (its kind): clients render it as a notice, and
// every reader that feeds the room back to an agent skips it (roomlog,
// notify: an agent must never read a notice as something it or another agent
// said). Every writer — the bridge, activity, the room tools — builds its row
// here (Payload, Report), and nothing else sets payload.notice
// (TestNoticesCarryKind).
export interface JobNotice {
  // Kind is payload.notice ("borrow-denied", NoticeProgress, …).
  Kind: string;
  // MessageID is the row's stable message id (idempotent on retry);
  // Kind-Session when empty.
  MessageID: string;
  // JobID and SourceSeq (the room sequence of the message that started
  // the job) let the feed nest the notice under its request.
  JobID: string;
  SourceSeq: number;
  Text: string;
  // Detail is the agent's or its core's own error output, verbatim but
  // cut (a failed turn's failMessage): never bnbloc's sentence and never
  // Markdown. Clients render it fenced (monospace, apart from Text).
  Detail: string;
  // OwnerUserID / Provider attribute the notice to the agent it is about.
  OwnerUserID: string;
  Provider: string;
  // FailReason is the job failure reason the notice reports ("" = none).
  FailReason: string;
  // Extra holds kind-specific fields (e.g. denyReason); it can never
  // override the fields above.
  Extra: Record<string, unknown>;
  // Where the row is recorded (Report). RoomID and ChannelID place it;
  // Session is the activity session it goes under
  // (JobNoticeSessionID(JobID) when empty): never a real agent session,
  // whose reply cursor a notice would move. Seq is its sequence there
  // (JobNoticeSeq when 0: one notice per job, a retry is a replay), and
  // AtUnixMs its creation time.
  RoomID: string;
  ChannelID: string;
  Session: string;
  Seq: number;
  AtUnixMs: number;
}

// Notice kinds written outside the bridge's refusal table (payload.notice).
// NoticeProgress is a team lead's progress line (post_progress).
export const NoticeProgress = "progress";
// NoticeTimeout is a team member that has not answered in time.
export const NoticeTimeout = "member-timeout";
// NoticeJobFailed is a job the server failed (a swept lease, a budget
// refusal at claim).
export const NoticeJobFailed = "job-failed";
// NoticeAttachmentUndelivered names a message's attachments that did not
// reach the agent's workspace, and why (the bridge, once per job, under
// AttachmentNoticeSessionID so the job's own notice still posts).
export const NoticeAttachmentUndelivered = "attachment-undelivered";
// NoticeContextReset says a turn outgrew its model's context window and
// continues in a fresh session (the bridge, at most once per job, under
// ContextResetNoticeSessionID so the job's own notice still posts).
export const NoticeContextReset = "context-reset";
// NoticeFileEdit says the file a request asked to change did not
// change: it never reached the agent (and why), or the agent left it
// as it was (the bridge, once per job, under FileEditNoticeSessionID).
export const NoticeFileEdit = "file-edit";

// ---- wire/job_progress.go ----

// EventAgentJobProgress carries AgentJobProgress (activity), scoped to the
// job's channel.
export const EventAgentJobProgress = "agent_job_progress";

// Job activity kinds (JobActivity.Kind): Core Protocol's turn activity
// kinds (core/protocol TurnActivity*; core/protocol TestTurnActivityIsTheWires).
// JobActivityTool: a step the agent ran (a command, a file read or
// written, a search).
export const JobActivityTool = "tool";
// JobActivityThinking: the agent is reasoning.
export const JobActivityThinking = "thinking";
// JobActivityText: the agent is writing.
export const JobActivityText = "text";

// Bounds of a job's progress (Core Protocol's MaxTurnActivity and
// MaxTurnActivityTitle; the bridge cuts to them).
export const MaxJobActivity = 8;
export const MaxJobActivityTitle = 120;

// JobActivity is one step of a live job's turn: a short title such as
// "Bash: python extract.py" (never file contents or secrets).
export interface JobActivity {
  kind: JobActivityKind;
  title?: string;
  atMs: number;
}

// AgentJobProgress is EventAgentJobProgress: a live job's turn start and
// latest steps, oldest first (at most MaxJobActivity). AtMs is when the
// bridge read it.
export interface AgentJobProgress {
  jobId: string;
  startedAtMs?: number;
  activity: JobActivity[];
  atMs: number;
}

// JobProgressInput is POST /v1/bridge/jobs/{jobId}/progress: the claiming
// bridge's report of its job's turn.
export interface JobProgressInput {
  bridgeId: string;
  startedAtMs?: number;
  activity: JobActivity[];
}

// ---- wire/limits.go ----

// Limits a service enforces and a client checks before it sends, so the
// client can say why instead of meeting a 4xx. Each is the one value the
// service enforces (and the web reads it from wire.gen.ts): a limit is
// changed here, never in a second copy.
// MaxUnreadRooms bounds one GET /v1/rooms-unread?rooms= query: each
// room costs a membership lookup and a count per channel. A longer list
// is refused (400), never cut, so a client never reads "no unread" into
// a truncated answer.
export const MaxUnreadRooms = 200;
// MaxAttachmentBytes bounds one chat attachment upload.
export const MaxAttachmentBytes = 26214400;
// MaxBlobBytes bounds one object in the blob store: realtime's blob put,
// so also an artifact version file (BNBLOC_ARTIFACT_MAX_BYTES may only
// lower it) and a super-admin artifact upload at the gateway.
export const MaxBlobBytes = 268435456;
// MaxArtifactStateBytes bounds one live collaboration-state payload. The
// state is transient but fans out to every room subscriber on each
// change, so it stays gesture-sized.
export const MaxArtifactStateBytes = 16384;
// MaxDisplayNameRunes is the longest display name accepted, in
// characters after trimming (Unicode code points, which is also how
// MySQL sizes the VARCHAR(40) column).
export const MaxDisplayNameRunes = 40;
// MaxContentTagRunes bounds one content component tag, in characters.
export const MaxContentTagRunes = 32;
// Media bounds (docs/prd/2026-10-16-voice-and-image-generation.md):
// what one media model call may carry. The gateway enforces them; the
// web reads them here to say why before it sends.
export const MaxMediaAudioBytes = 20971520;
export const MaxMediaTranscriptChars = 32768;
export const MaxMediaImagePrompt = 4000;
export const MaxMediaImageReplyBytes = 16777216;
export const MaxMediaImageBytes = 12582912;
export const MaxMediaImages = 4;
export const MaxMediaImageInputs = 4;

// ContentTagPattern is the one rule for a content component tag: lower-case
// letters of any script (CJK and other caseless letters included), digits,
// spaces, '_' and '-', starting with a letter or digit. It is valid both as
// Go RE2 and as a JavaScript regular expression with the "u" flag.
export const ContentTagPattern = "^[\\p{Ll}\\p{Lo}\\p{Nd}][\\p{Ll}\\p{Lo}\\p{Nd} _-]*$";

// The safety caps of an interactive app's data (docs/prd/2026-10-12-
// interactive-apps.md §4.5): cost and abuse bounds, not product rules. The
// room service (services/room/appdata.go) enforces them; the app SDK checks
// them before it sends.
// MaxAppDocBytes bounds one document: its JSON body without the server
// stamps.
export const MaxAppDocBytes = 65536;
// MaxAppDocs bounds the documents of one app, all collections together.
export const MaxAppDocs = 100000;
// MaxAppBytes bounds the stored bytes of one app's documents.
export const MaxAppBytes = 268435456;
// MaxAppCollections bounds the named collections of one app.
export const MaxAppCollections = 64;
// MaxAppCollectionNameLen bounds a collection name (letters, digits,
// '_' and '-').
export const MaxAppCollectionNameLen = 64;
// MaxAppDocIDLen bounds a document id (letters, digits, '_', '-', '.'
// and ':').
export const MaxAppDocIDLen = 128;
// MaxAppFindLimit bounds one page of a find.
export const MaxAppFindLimit = 500;
// MaxAppRequestBytes bounds one app data request body: a document plus
// its envelope (AppDocWrite, AppDocPatch).
export const MaxAppRequestBytes = 69632;
// MaxAppFiles and MaxAppFileBytes bound the files one app's pages
// uploaded (app.files), apart from its documents: a form collecting
// photos must not crowd out its own answers. One file is at most
// MaxAttachmentBytes, a chat attachment's cap.
export const MaxAppFiles = 10000;
export const MaxAppFileBytes = 2147483648;
// MaxAppUploadBytes bounds an upload's request body: one file and its
// multipart envelope.
export const MaxAppUploadBytes = 26230784;
// MaxAppAIPrompt and MaxAppAIInput bound an app's ai call, in
// characters: its instruction, and the data it works on (a week of a
// team's logs).
export const MaxAppAIPrompt = 8000;
export const MaxAppAIInput = 60000;
// MaxAppNotifyLogins bounds the logins one app notice names, and
// MaxAppNotifyRecipients the people it reaches (a room's members
// included).
export const MaxAppNotifyLogins = 100;
export const MaxAppNotifyRecipients = 500;

// The caps of a work (docs/prd/2026-10-13-works-gallery-and-make-similar.md):
// contentpkg's work kind enforces them.
// MaxWorkCoverBytes bounds a work's cover image (cover.png, .jpg or
// .webp at the bundle's root, or an image work's image): a larger one
// is not served, and the card draws the generated cover.
export const MaxWorkCoverBytes = 1048576;
// MaxWorkReferences bounds the reference files a work's recipe keeps
// (the request's attachments, in order; the rest are left out).
export const MaxWorkReferences = 8;
// MaxWorkReferenceBytes bounds the reference files of a work together.
export const MaxWorkReferenceBytes = 26214400;

// ---- wire/mcp_tools.go ----

// ContentMCPRequirement is one requires.mcp entry of a package: an MCP tool
// component by name, and the component's env names the package needs set.
export interface ContentMCPRequirement {
  name: string;
  env?: string[];
}

// RoomRelayRoutes are the gateway routes a room-credential MCP tool reaches
// through the bridge's room relay ("METHOD /path"; pkgmeta.MCPCredentialsRoom):
// each admits a job grant (?room=&job=) and acts as the job's requester. A
// route joins the list only with that admission; the relay refuses the
// rest.
export const RoomRelayRoutes: readonly string[] = ["POST /v1/decisions", "POST /v1/systemone", "POST /v1/media/image", "POST /v1/media/transcriptions"];

// RoomRelaySessionPath is the relay's own route that answers the bound
// turn (GET <relay>/session): RoomRelaySession. It is the bridge's, never
// a gateway route.
export const RoomRelaySessionPath = "/session";

// RoomRelaySession is the turn a room-credential tool's session is driving
// now, as the relay knows it: who the calls act for (Requester), whose
// machine and agent it is (Owner), where the turn was asked (Room,
// Channel) and by which message (MessageSeq, increasing in the room).
// ByRequester marks a turn its requester opened with their own typed
// message (not a schedule's post, not another agent's dispatch): a tool
// that paused for a person's answer accepts it only in such a turn, newer
// than the pause.
export interface RoomRelaySession {
  jobId: string;
  roomId: string;
  channelId?: string;
  requester: string;
  owner: string;
  messageSeq: number;
  byRequester: boolean;
}

// MCP transports of a resolved tool (ContentMCPTool.Transport).
export const MCPTransportStdio = "stdio";
export const MCPTransportHTTP = "http";

// ContentMCPTool is one MCP tool component in effect for a job's turn, as
// the bridge driving it needs it. Values carries an org connector's values
// (secrets): it is answered only to the bridge holding the job's lease and
// never logged or persisted.
export interface ContentMCPTool {
  name: string;
  version: string;
  transport: string;
  // Artifacts are a stdio server's sha256 pins by platform
  // ("darwin-arm64"): the bridge uses the desktop's materialized binary
  // only when it carries this platform's pin.
  artifacts?: Record<string, string>;
  args?: string[];
  // URL and Auth describe an http server.
  url?: string;
  auth?: ContentMCPAuth;
  env?: ContentMCPEnv[];
  // Credentials is "member" or "org" ("" when the tool takes no env).
  credentials?: string;
  values?: Record<string, string>;
  // RequiredBy are the ids of the packages in effect that require it.
  requiredBy: string[];
}

// ContentMCPAuth is the header an http MCP server expects (scheme none,
// bearer or header, Env naming the value's variable; or oauth: the
// requester's own sign-in from their desktop, attached as a bearer token by
// their bridge and never lent to someone else's drive).
export interface ContentMCPAuth {
  scheme: string;
  header?: string;
  env?: string;
}

// ContentMCPEnv is one variable a resolved tool takes; Required means the
// turn needs it set (declared required, or named by a requiring package).
export interface ContentMCPEnv {
  name: string;
  secret?: boolean;
  required?: boolean;
}

// MCPConnectorField is one variable of an org connector as an org admin
// sees it: a secret value is never returned (Set says whether one is
// stored).
export interface MCPConnectorField {
  name: string;
  description?: string;
  secret?: boolean;
  required?: boolean;
  set: boolean;
  value?: string;
}

// MCPConnector is one org-credential MCP tool component visible to the
// organization, with its connector's state.
export interface MCPConnector {
  name: string;
  version: string;
  description?: string;
  transport: string;
  configured: boolean;
  fields: MCPConnectorField[];
  updatedBy?: string;
  updatedAtMs?: number;
}

// MCPConnectorsReply answers GET /v1/tenant/mcp-connectors. Available is
// false when the gateway has no secret store key (org connectors are off).
export interface MCPConnectorsReply {
  available: boolean;
  connectors: MCPConnector[];
}

// MCPConnectorUpdate is PUT /v1/tenant/mcp-connectors/{name}: the values to
// store (an empty secret keeps the stored one).
export interface MCPConnectorUpdate {
  values: Record<string, string>;
}

// ---- wire/media.go ----

// MediaCapabilities is GET /v1/media: which media calls run for the caller
// (a configured provider and an organization that has not turned AI off).
export interface MediaCapabilities {
  transcribe: MediaCapability;
  image: MediaCapability;
}

// MediaCapability is one media ability as the caller sees it.
export interface MediaCapability {
  // Available: a provider is configured for the caller's organization.
  available: boolean;
  // Models are the provider's models the caller may pick from (the first
  // the default); empty when the provider serves one.
  models?: string[];
}

// MediaProviderConfig is GET /v1/platform/media/{capability}: the
// capability's providers. The key is never returned, only whether one is
// set. kind names the wire protocol adapter (media.AdapterKind*); auth is
// "key" (a sealed deployment key) or "caller" (each caller's own session
// token is forwarded — a proxy that bills the caller, like the platform's
// own LLM gateway).
export interface MediaProviderConfig {
  configurable: boolean;
  kind: string;
  baseUrl: string;
  model: string;
  // Models are the models a call may name (the provider serves them all);
  // Model is the first of them, the default.
  models?: string[];
  auth: string;
  keySet: boolean;
  // OrgHosts are the hosts an organization's own provider may name (the
  // platform row only; none = organizations cannot set their own).
  orgHosts: string[];
  // Params is the provider's own knobs as the admin set them.
  params?: Record<string, string>;
  updatedBy?: string;
  updatedAtMs?: number;
}

// MediaOrgProvider is GET /v1/tenant/media/{capability}: the organization's
// own provider (BaseURL "" = it uses the platform's) and the hosts it may
// name.
export interface MediaOrgProvider {
  provider: MediaProviderConfig;
  // AllowedHosts are the platform's orgHosts; empty = an organization
  // cannot set its own provider.
  allowedHosts: string[];
  // PlatformModel names the platform's model ("" = none), shown as what
  // members use when the organization sets none.
  platformModel?: string;
}

// MediaProviderUpdate is PUT /v1/platform/media/{capability}: an empty APIKey
// keeps the stored one, ClearKey removes it, an empty BaseURL turns the
// capability off. Kind must name a registered adapter.
export interface MediaProviderUpdate {
  kind: string;
  baseUrl: string;
  model: string;
  // Models are the models a call may name; Model is the first of them.
  models?: string[];
  // Auth is "key" (default: a sealed API key) or "caller" (forward the
  // caller's own session token).
  auth?: string;
  apiKey?: string;
  clearKey?: boolean;
  // OrgHosts is the platform's to set (the hosts organizations may name);
  // an update without it keeps the stored ones.
  orgHosts?: string[];
  params?: Record<string, string>;
}

// MediaProviderTest is POST /v1/platform/media/{capability}/test: one real
// short call through the stored provider.
export interface MediaProviderTest {
  ok: boolean;
  error?: string;
  // Reply is what the provider answered, bounded (a transcript line, or
  // nothing for an image test).
  reply?: string;
  // LatencyMs is the call's wall time.
  latencyMs: number;
}

// MediaTranscribeReply is POST /v1/media/transcriptions: the transcript,
// capped at MaxMediaTranscriptChars characters.
export interface MediaTranscribeReply {
  text: string;
}

// Image aspect ratios a generation may ask for.
export const MediaImageAspectSquare = "square";
export const MediaImageAspectLandscape = "landscape";
export const MediaImageAspectPortrait = "portrait";

// MediaImageAspects are the aspects a generation may ask for.
export const MediaImageAspects: readonly string[] = ["square", "landscape", "portrait"];

// MediaImageRequest is POST /v1/media/image.
export interface MediaImageRequest {
  // Prompt is what to draw, at most MaxMediaImagePrompt characters.
  prompt: string;
  // Model is one of the provider's models (MediaProviderConfig.Models);
  // the first is the default.
  model?: string;
  // Aspect defaults to MediaImageAspectSquare.
  aspect?: MediaImageAspect;
  // Count is how many images to draw in one provider call (1…MaxMediaImages,
  // default 1): one request's cost, not n.
  count?: number;
  // Image, when set, is the image to change (an edit) instead of drawing a
  // new one: a data URL the caller holds (a previous reply's, an
  // attachment's bytes the caller may read). At most MaxMediaImageBytes.
  image?: string;
  // Publish, when true in a room (an agent's job grant, ?job=&room=, or a
  // room app's page), publishes each drawn image into the room's Docs: the
  // reply carries each image's artifactId. A member's own call (no room)
  // never publishes.
  publish?: boolean;
  // FileName, with Publish, names the first image (poster.png); the rest
  // are numbered (poster-2.png…).
  fileName?: string;
  // ArtifactID, in a room (as Publish), is the room image to edit: it is
  // read as the caller (a job's requester, an app's participant), and the
  // result is published as its next version
  // (docs/prd/2026-10-17-image-generation-redesign.md §2.2).
  artifactId?: string;
  // Region, with an edit, is the part of the image to change, in its own
  // pixels: the provider gets a mask.
  region?: MediaImageRegion;
  // Inputs, in a room, are room files (art_…) and attachments (att_…) the
  // prompt uses as references, at most MaxMediaImageInputs, read as the
  // caller. Without ArtifactID the first is the image to change.
  inputs?: string[];
}

// MediaImageRegion is a rectangle of an image in its own pixels, origin at
// the top-left. With Mask, the area a member painted: Mask is the message's
// mask attachment (att_…, a PNG of the image's size, transparent where it
// may change), which is the edit's mask, and the rectangle is its bounding
// box (docs/prd/2026-10-17-image-generation-redesign.md §2.7).
export interface MediaImageRegion {
  x: number;
  y: number;
  w: number;
  h: number;
  mask?: string;
}

// MediaImageReply is POST /v1/media/image's answer: the images inline
// (dataUrl), never a link out to another host. One answer per Count ask.
export interface MediaImageReply {
  images: MediaImage[];
}

// MediaImage is one generated (or edited) image.
export interface MediaImage {
  dataUrl?: string;
  // ArtifactID, when the call published, is the room artifact the image
  // became (and DataURL is empty: the image is not also inlined); Version
  // its version (above 1 for an edit), FileName its name, and Note what
  // happened when it is not what was asked (an edit saved as a new file).
  artifactId?: string;
  version?: number;
  fileName?: string;
  note?: string;
  mimeType: string;
  width: number;
  height: number;
  // RevisedPrompt is the provider's own rewording, when it sends one: data
  // the provider wrote, fenced wherever an agent reads it.
  revisedPrompt?: string;
}

// ---- wire/my_agents.go ----

// MyAgent is one agent the caller's own bridge advertises (any room).
// Online is false while the owner disabled it.
export interface MyAgent {
  core: string;
  provider: string;
  targetId: string;
  online: boolean;
  modelOptions?: AgentModelOptions;
}

// MyDesktop is the caller's own desktop app, apart from its agents: Online
// is its bridge connected now (even with no agent core); LastSeenAtMs the
// latest connection, 0 when the app never connected (not installed).
export interface MyDesktop {
  online: boolean;
  lastSeenAtMs: number;
}

// MyAgentsReply is GET /v1/my/agents: the same agent list the member's
// desktop app shows, because both render what their bridge advertises.
export interface MyAgentsReply {
  agents: MyAgent[];
  desktop: MyDesktop;
}

// ---- wire/my_apps.go ----

// MyApp is one app of the listing.
export interface MyApp {
  // AppID is the site artifact's id (the app's data space is keyed by it).
  appId: string;
  name: string;
  roomId: string;
  roomName: string;
  version: number;
  updatedAtMs: number;
  // Producer made the latest version.
  producer: AppProducer;
  // Documents is the app's document count (its owners' stats); 0 when
  // the app holds no data.
  documents: number;
  // Links are the app's share links that work now (not revoked, not
  // expired), newest first.
  links: AppLink[];
}

// AppProducer is who produced a version: an agent (Owner, Provider, Core),
// or a person (Person) for a manual publish; empty when the source job's
// run record is gone.
export interface AppProducer {
  owner?: string;
  provider?: string;
  core?: string;
  person?: string;
}

// AppLink is one working share link of an app.
export interface AppLink {
  shareId: string;
  access: ShareAccess;
  expiresAtMs: number;
  // Version is the pinned version; 0 follows the latest.
  version: number;
}

// MyAppList is GET /v1/my/apps; NextCursor pages on (absent on the last
// page).
export interface MyAppList {
  apps: MyApp[];
  nextCursor?: string;
}

// ---- wire/notifications.go ----

// Notification types carried in NotificationPayload.Type.
export const NotificationMention = "mention";
export const NotificationAgentFinished = "agent_finished";
export const NotificationAgentFailed = "agent_failed";
export const NotificationBorrowRequest = "borrow_request";
// NotificationTest is only sent by a "send test notification" action
// (super-admin or member); it is never produced by room activity.
export const NotificationTest = "test";
// NotificationAdminAlert is an operational alert a super-admin (or an
// unattended job such as the nightly smoke) sends to platform admins
// (POST /v1/platform/alerts). It has no room and is delivered to exactly
// the listed recipients: member preferences, muted rooms and burst
// collapsing do not apply.
export const NotificationAdminAlert = "admin_alert";
// NotificationBudgetWarning tells a member (member budget) or the org
// admins (tenant budget) that this month's usage budget crossed its
// warning threshold or was reached (R12). Room-less and operational,
// like an admin alert: sent once per threshold per month.
export const NotificationBudgetWarning = "budget_warning";
// NotificationContentShared tells a member that an author shared an
// expert, skill pack or prompt pack with them (a copy in their Library).
// Room-less; it links to the Library.
export const NotificationContentShared = "content_shared";
// NotificationContentReview tells an organization's admins that a
// content component waits for their approval, and its author how they
// decided. Room-less; it links to the Organization console or the
// Library.
export const NotificationContentReview = "content_review";
// NotificationAppNotice is a notice an interactive app sent to the
// room's members or to named people of the organization (app.notify):
// its title is the app's, and it links to the app.
export const NotificationAppNotice = "app_notice";

// AdminAlertRequest is the body of POST /v1/platform/alerts. Recipients
// default to every configured platform super-admin.
export interface AdminAlertRequest {
  title: string;
  text?: string;
  url?: string;
  recipients?: string[];
}

// AdminAlertResponse answers an accepted alert: the event id (the
// notifier's idempotency key), the recipients, and the notifier components
// it was queued for. Delivery is asynchronous through the outbox.
export interface AdminAlertResponse {
  id: string;
  recipients: string[];
  notifiers: string[];
}

// Notification delivery headers.
// NotificationSignatureHeader carries "t=<unix seconds>,v1=<hex>" where
// v1 = HMAC-SHA256(secret, t + "." + body).
export const NotificationSignatureHeader = "X-Bnbloc-Signature";
// NotificationEventIDHeader repeats NotificationPayload.ID so a receiver
// can de-duplicate retries without parsing the body.
export const NotificationEventIDHeader = "X-Bnbloc-Event-Id";

// NotificationPrefs is a member's notification settings
// (GET/PUT /v1/my/notification-prefs). Defaults: every type on, no quiet rooms.
export interface NotificationPrefs {
  mentions: boolean;
  agentFinished: boolean;
  agentFailed: boolean;
  borrowRequests: boolean;
  contentShared: boolean;
  contentReview: boolean;
  appNotices: boolean;
  quietRooms: string[];
}

// NotificationTestResult answers a test send (POST
// /v1/platform/components/{name}/test and POST /v1/my/notifiers/{name}/test).
// Delivered is true when the notifier answered 2xx and reported no failed
// recipient; Results is the notifier's per-recipient report.
export interface NotificationTestResult {
  delivered: boolean;
  status?: number;
  error?: string;
  eventId: string;
  results?: NotificationRecipientResult[];
}

// NotificationRecipient is one recipient of a notification.
export interface NotificationRecipient {
  userId: string;
  // ReplyToken (N1) is present when the notification accepts a reply
  // (NotificationPayload.Reply set): an opaque per-recipient token the
  // notifier sends back with POST /v1/notifier/replies to post the
  // member's answer into the room. Minted per delivery attempt, valid for
  // 7 days (notify.ReplyTokenTTL); never logged.
  replyToken?: string;
}

// NotificationReply (N1) says where a reply to a notification goes: the room
// channel, and — for an agent outcome — the agent the reply is addressed to
// (the same {ownerId, provider, core} recipient the member's request used;
// borrow rules apply when the member drives another member's agent). A nil
// Recipient posts human chat to the room (a mention).
export interface NotificationReply {
  channelId?: string;
  recipient?: NotificationReplyRecipient;
}

// NotificationReplyRecipient is the agent a reply is addressed to.
export interface NotificationReplyRecipient {
  ownerId: string;
  provider: string;
  core?: string;
}

// Notifier reply seam (N1): a notifier component posts a member's reply to a
// notification back into bnbloc.
// NotifierRepliesPath is the gateway route a notifier posts replies to.
export const NotifierRepliesPath = "/v1/notifier/replies";
// NotifierComponentHeader names the notifier component that signed a
// reply (X-Bnbloc-Signature uses that component's signing secret).
export const NotifierComponentHeader = "X-Bnbloc-Component";

// NotifierReplyRequest is the signed body of POST /v1/notifier/replies.
// IdempotencyKey is the receiving system's id of the reply message: a retry
// with the same key never posts twice. The reply names its token either
// directly (ReplyToken) or (R9) by a reference the notifier registered with
// POST /v1/notifier/reply-refs: Ref is the message the member answered and
// Sender the receiving system's account that answered — it must be the
// account the reference was registered for. Exactly one of the two forms.
export interface NotifierReplyRequest {
  replyToken?: string;
  ref?: string;
  sender?: string;
  text: string;
  idempotencyKey: string;
}

// NotifierReplyRefsPath (R9) is the gateway route a notifier registers reply
// references at.
export const NotifierReplyRefsPath = "/v1/notifier/reply-refs";

// NotifierReplyRefRequest is the signed body of POST /v1/notifier/reply-refs:
// the notifier sent the notification carrying ReplyToken as the receiving
// system's message Ref to the account Recipient (both opaque, at most 128
// characters). A reply quoting Ref from Recipient then resolves to the token
// in bnbloc, so the notifier keeps no state of its own.
export interface NotifierReplyRefRequest {
  replyToken: string;
  ref: string;
  recipient: string;
}

// NotifierReplyResponse answers an accepted reply with the posted message's
// room sequence (the original sequence for an idempotent retry).
export interface NotifierReplyResponse {
  roomId: string;
  sequence: number;
}

// NotificationRecipientResult is a notifier's per-recipient outcome. A failed
// recipient with Retryable=true is re-sent later (same event id, recipients
// narrowed to the retryable failures); a non-retryable failure is final.
export interface NotificationRecipientResult {
  userId: string;
  ok: boolean;
  error?: string;
  retryable?: boolean;
}

// NotificationDeliveryResponse is the optional 2xx body of a notifier.
export interface NotificationDeliveryResponse {
  results: NotificationRecipientResult[];
}

// MemberNotifier is one notifier component as a member sees it
// (GET /v1/my/notifiers).
export interface MemberNotifier {
  name: string;
  description?: string;
  // OptIn is true for an opt-in component; Installed then says whether the
  // member opted in (only opted-in members receive its notifications).
  optIn: boolean;
  installed: boolean;
}

// NotificationPayload is the signed JSON body posted to a notifier
// component (POST {baseUrl}/v1/notifications).
export interface NotificationPayload {
  id: string;
  type: string;
  tenantId: string;
  roomId: string;
  roomName: string;
  recipients: NotificationRecipient[];
  actor: string;
  title: string;
  text: string;
  url?: string;
  atMs: number;
  // Reply (N1) is set when the notification accepts a reply (mention,
  // agent_finished, agent_failed): each recipient then carries a
  // ReplyToken.
  reply?: NotificationReply;
  // Group, when set, addresses the notification to a group chat a room
  // connected through this notifier instead of members: Recipients is
  // empty, GroupAddress is the notifier's own address of the chat (what
  // it reported when the chat was connected). Only a notifier declaring
  // the groups capability receives one.
  group?: string;
  groupAddress?: string;
}

// ---- wire/payloads.go ----

// ChatMessagePayload is the payload of a chat_message event (realtime's
// PostChat writes it; readers ignore fields they do not know).
export interface ChatMessagePayload {
  // UserID is the author.
  userId: string;
  text: string;
  // ClientMsgID echoes the sender's idempotency id.
  clientMsgId?: string;
  // Recipient addresses one member's agent; nil = people only.
  recipient?: ChatRecipientRef;
  attachments?: ChatAttachment[];
  // DispatchedBy marks a task an agent dispatched through the room tools.
  dispatchedBy?: DispatchMarker;
  // Imported marks a row a handoff import wrote.
  imported?: ImportedMarker;
}

// ChatRecipientRef is the agent a chat message addresses.
export interface ChatRecipientRef {
  ownerId: string;
  provider: string;
  core?: string;
}

// FileRef names the room file a chat message is about: a deliverable at a
// version, which the agent edits (docs/prd/2026-10-14-ai-document-editing.md
// rules 2–4). Name is the file's display name, filled by the server.
export interface FileRef {
  artifactId: string;
  version: number;
  name?: string;
  // Selection is the part of the file the member points at (rule 5): the
  // previewer's chip label and the content it names. It reaches the agent
  // as the file's data, never as the member's words.
  selection?: FileSelection;
}

// FileSelection is a previewer's selection (preview.selection): Label
// 1–MaxFileSelectionLabel characters, Detail at most MaxFileSelectionDetail.
export interface FileSelection {
  label: string;
  detail?: string;
  // Kind is what was selected (FileSelectionKinds; "" = not said).
  kind?: string;
  // Keys are the Compare unit keys the selection covers (a slide's, every
  // cell of a range), at most MaxFileSelectionKeys: the change card names
  // edits outside them (docs/prd/2026-10-14-select-edit-review.md rule 5).
  keys?: string[];
  // Mask is an area painted on an image (kind region): a PNG attachment
  // of the room (att_…) the image's size, transparent where it may change
  // (docs/prd/2026-10-17-image-generation-redesign.md §2.7).
  mask?: string;
}

// FileSelectionKinds is the code-owned vocabulary of selection kinds,
// equal to the frame protocol's SELECTION_KINDS (core/pkgmeta's vocabulary
// test compares them). Prompt packs scope selection suggestions by it.
export const FileSelectionKinds: readonly string[] = ["text", "block", "slide", "cells", "region", "time"];

// The selection bounds, equal to the frame protocol's SELECTION_*_LIMIT
// (core/pkgmeta's vocabulary test compares them).
export const MaxFileSelectionLabel = 120;
export const MaxFileSelectionDetail = 2000;
export const MaxFileSelectionKeys = 500;
export const MaxFileSelectionKey = 200;

// ChatAttachment is an attachment a chat message embeds.
export interface ChatAttachment {
  id: string;
  filename: string;
  contentType: string;
  size: number;
}

// AgentMessagesPayload is the payload of an agent_messages event: the batch
// a bridge (or a JobNotice writer) reported (ReportMessagesInput), with each
// message's payload read as an AgentMessageBody.
export interface AgentMessagesPayload {
  workspaceId: string;
  agentSessionId: string;
  channelId?: string;
  messages: AgentMessage[];
}

// AgentMessage is one reported message of an agent_messages batch.
export interface AgentMessage {
  seq: number;
  payload: AgentMessageBody;
  createdAtUnixMs: number;
}

// AgentMessageBody is the read view of one agent message.
export interface AgentMessageBody {
  messageId: string;
  role: string;
  text: string;
  ownerUserId: string;
  provider: string;
  core?: string;
  // Notice is the notice kind of a JobNotice line ("" for the agent's
  // own message).
  notice?: string;
  jobId?: string;
}

// ---- wire/platform_agents.go ----

// PlatformAgentRef names an agent by its core and provider.
export interface PlatformAgentRef {
  core: string;
  provider: string;
}

// PlatformAgentSpec is one agent a host publishes. DefaultModel (optional)
// is the model a platform turn runs with when the chat carried no explicit
// model; members may still pick another.
export interface PlatformAgentSpec {
  core: string;
  provider: string;
  defaultModel?: string;
}

// PlatformAgentHost is one super admin's published agents: their entry in
// the policy. Only that super admin writes it.
export interface PlatformAgentHost {
  hostUserId: string;
  enabled: boolean;
  agents: PlatformAgentSpec[];
}

// PlatformAgentsPolicy is the platform setting `platform_agents` and the
// answer of GET/PUT /v1/platform/platform-agents: one entry per host. PUT
// {enabled, agents} replaces the caller's entry only.
export interface PlatformAgentsPolicy {
  hosts: PlatformAgentHost[];
}

// PublishedHost is one host publishing an agent, with its spec.
export interface PublishedHost {
  HostUserID: string;
  Spec: PlatformAgentSpec;
}

// PublishedAgent is a platform agent and every host publishing it now.
export interface PublishedAgent {
  Ref: PlatformAgentRef;
  Hosts: PublishedHost[];
}

// PlatformAgentHostState is one host of a platform agent as members see it.
// Online: the host's live bridge advertises the agent; TargetID is the
// core-qualified target it advertises (as in GET /v1/my/agents; empty while
// offline); Queued counts the jobs addressed to this host's agent that have
// not started yet (queued or claimed, across organizations); DefaultModel is
// the host's default for the agent ("" = the core's own default).
export interface PlatformAgentHostState {
  hostUserId: string;
  online: boolean;
  queued: number;
  targetId: string;
  defaultModel?: string;
}

// PlatformAgent is one platform agent (core, provider) as members see it,
// with the state of each host serving it. Online is true when any host is.
// In a room's listing Hosts are the hosts that serve the room, and
// AddedBy/AddedAtMs say who added the agent there and when (the earliest
// grant).
export interface PlatformAgent {
  core: string;
  provider: string;
  online: boolean;
  hosts: PlatformAgentHostState[];
  addedBy?: string;
  addedAtMs?: number;
}

// PlatformAgentsReply is GET /v1/platform-agents and
// GET /v1/rooms/{roomId}/platform-agents.
export interface PlatformAgentsReply {
  agents: PlatformAgent[];
}

// ErrPlatformAgentOffline is the 409 error code of a chat addressed to a
// platform agent whose host is not online (no job is created).
export const ErrPlatformAgentOffline = "platform_agent_offline";

// PlatformAgentOfflineReply is that 409 body.
export interface PlatformAgentOfflineReply {
  error: string;
  message: string;
  hostUserId: string;
  core: string;
  provider: string;
}

// PlatformAgentUsageTotals are the platform-agent runs of one period:
// distinct members and rooms, reported tokens (input + output) and cost.
export interface PlatformAgentUsageTotals {
  runs: number;
  members: number;
  rooms: number;
  tokens: number;
  cost: number;
}

// PlatformAgentUsageMember is one member's platform-agent use this month.
export interface PlatformAgentUsageMember {
  memberId: string;
  runs: number;
  tokens: number;
  cost: number;
}

// PlatformAgentUsageRoom is one room's platform-agent use this month.
export interface PlatformAgentUsageRoom {
  roomId: string;
  roomName: string;
  tenantId: string;
  runs: number;
  tokens: number;
  cost: number;
}

// PlatformAgentUsageRun is one platform-agent run. Agent is "core/provider";
// Model is what the core reported (else the requested or default model);
// Cost is what the host's bridge reported (0 when unpriced or unreported).
export interface PlatformAgentUsageRun {
  atMs: number;
  memberId: string;
  roomId: string;
  roomName: string;
  tenantId: string;
  agent: string;
  hostUserId: string;
  model: string;
  cost: number;
}

// PlatformAgentUsageReply is GET /v1/platform/platform-agents/usage (super
// admin): today's and this month's totals (UTC), the top 5 members and rooms
// of the month by runs, and the last 20 runs, newest first, across every
// organization. Truncated: the month's scan hit its row cap.
export interface PlatformAgentUsageReply {
  today: PlatformAgentUsageTotals;
  month: PlatformAgentUsageTotals;
  topMembers: PlatformAgentUsageMember[];
  topRooms: PlatformAgentUsageRoom[];
  recent: PlatformAgentUsageRun[];
  truncated: boolean;
}

// ---- wire/plugins.go ----

// PluginEventKind is the SSE event name of one PluginDelivery frame.
export const PluginEventKind = "plugin_event";

// ComponentsChangedKind is the SSE event name of a ComponentsChanged hint on
// the same member stream: the member's executable component catalog
// (GET /v1/components) changed, so the desktop refreshes it now instead of
// at its next poll. The stream doubles as the member's desktop channel; a
// desktop holds it whenever its sidecar manager runs, with ?plugins=1 only
// while it runs a plugin sidecar (plugin deliveries and notification routing
// consider only those streams).
export const ComponentsChangedKind = "components_changed";

// ComponentsChanged is the body of realtime's internal
// POST /internal/v1/components/changed (the gateway's signal after a catalog
// change, and the hand-off between realtime replicas) and the data of a
// components_changed frame. It is a hint, not the change: the desktop
// re-reads its catalog. TenantID scopes it to the members signed in to one
// organization ("" = every member); Member scopes it to one member (an
// opt-in install or removal).
export interface ComponentsChanged {
  tenantId?: string;
  member?: string;
  atMs: number;
}

// Plugin delivery outcomes a desktop acknowledges (PluginDeliveryAck.Status).
export const PluginDeliveryDelivered = "delivered";
export const PluginDeliveryFailed = "failed";

// PluginEnvelope is what a plugin sidecar receives at POST /events: the hook's
// versioned event name and an immutable copy of the source event payload.
export interface PluginEnvelope {
  event: string;
  version: string;
  tenantId: string;
  roomId: string;
  payload: unknown;
}

// PluginDelivery is one frame of a member's plugin event stream: the delivery
// id to acknowledge, the plugin it targets, and the envelope to post verbatim.
export interface PluginDelivery {
  id: string;
  plugin: string;
  envelope: unknown;
}

// PluginDeliveryAck reports how the desktop's POST /events went.
export interface PluginDeliveryAck {
  status: string;
  detail?: string;
}

// PluginNotification is the payload of a notification.v1 delivery: ONE
// member's notification, sent to that member's own desktop plugin (e.g. a
// personal bot), which delivers it in place of the server notifiers. The
// member's preferences, muted rooms and burst collapsing were already applied.
export interface PluginNotification {
  // ID is the logical event id (the server notifiers' X-Bnbloc-Event-Id):
  // stable across retries, so a plugin can de-duplicate on (id, userId).
  id: string;
  type: string;
  // UserID is the member this notification is for (their bnbloc subject,
  // typically the IdP email).
  userId: string;
  roomId?: string;
  roomName?: string;
  channelId?: string;
  // Seq is the room message the notification is about (0 = none).
  seq?: number;
  actor: string;
  title: string;
  text: string;
  // URL is the web deep link (absent without BNBLOC_PUBLIC_URL).
  url?: string;
  atMs: number;
  // Reply is set when the member may answer: the plugin posts the answer
  // as a normal chat message through the desktop host API
  // (POST {BNBLOC_PLUGIN_HOST_URL}/v1/chat) addressed as here.
  reply?: PluginNotificationReply;
}

// Reply targets of a PluginNotificationReply.
export const PluginReplyToRoom = "room";
export const PluginReplyToAgent = "agent";

// PluginNotificationReply says where an answer goes: the room channel as
// human chat (To "room", a mention), or the agent the member's request
// addressed (To "agent": the chat recipient {ownerId, provider, core};
// borrow rules apply as for any typed message).
export interface PluginNotificationReply {
  roomId: string;
  channelId?: string;
  to: string;
  agent?: NotificationReplyRecipient;
}

// ---- wire/profiles.go ----

// UserProfile is one user's public profile: GET /v1/users/profiles answers
// {profiles: [UserProfile]} for any id, never with more than the display
// name. DisplayName always has the default applied (store.DisplayName).
export interface UserProfile {
  userId: string;
  displayName: string;
}

// MyProfile is the caller's own profile (GET/PUT /v1/my/profile).
// DisplayName has the default applied; IsDefault reports that no name is
// set (so a settings form shows an empty field with the default as hint).
export interface MyProfile {
  userId: string;
  displayName: string;
  isDefault: boolean;
}

// ---- wire/retention.go ----

// RetentionKind is one kind of data a retention policy covers.
export type RetentionKind = "messages" | "artifactVersions" | "audit" | "agentJobs";

// Retention kinds.
// RetentionMessages: room messages (chat and agent replies, with their
// message tasks), the activity copy of agent replies, and chat
// attachments, by age.
export const RetentionMessages = "messages";
// RetentionArtifactVersions: artifact versions other than the latest
// (with the share links pinned to them). The latest version is never
// deleted.
export const RetentionArtifactVersions = "artifactVersions";
// RetentionAudit: the audit trails (borrow decisions, component and
// administration events).
export const RetentionAudit = "audit";
// RetentionAgentJobs: agent jobs that finished (replied, failed, timed
// out or cancelled). Queued and running jobs are never deleted.
export const RetentionAgentJobs = "agentJobs";

// RetentionKinds lists every kind, in display order.
export const RetentionKinds: readonly RetentionKind[] = ["messages", "artifactVersions", "audit", "agentJobs"];

// Retention bounds. The minimum is one month because monthly usage budgets
// and the borrow usage reports read the current month's agent replies and
// audit rows; a shorter period would undercount them. They are properties
// of the product (the budget period), not of a deployment.
export const RetentionMinDays = 31;
export const RetentionMaxDays = 36500;

// RetentionLimits tells a client the accepted range of a days value.
export interface RetentionLimits {
  minDays: number;
  maxDays: number;
}

// RetentionPolicy holds the days of each kind. What an unset (null) value
// means depends on the layer:
//
//   - the platform default: null keeps forever (0 is accepted on write and
//     stored as null);
//   - a tenant override: null uses the platform default, 0 keeps forever
//     (overriding a platform default), N deletes after N days.
//
// The effective policy (EffectiveRetention) holds null for keep forever.
export interface RetentionPolicy {
  messagesDays: number | null;
  artifactVersionsDays: number | null;
  auditDays: number | null;
  agentJobsDays: number | null;
}

// RetentionStatus is what the retention worker last did (platform-wide).
export interface RetentionStatus {
  // LastRunAtMs is when the last row-deletion pass finished (0 = never).
  lastRunAtMs: number;
  // LastBlobGCAtMs is when the last blob collection finished (0 = never).
  lastBlobGcAtMs: number;
  // LastDeleted counts what the last pass deleted, by item (room
  // messages, attachments, blobs, ...).
  lastDeleted: Record<string, number>;
}

// PlatformRetentionView is GET/PUT /v1/platform/retention: the platform
// default (null = keep forever), the accepted range and the worker status.
export interface PlatformRetentionView {
  default: RetentionPolicy;
  limits: RetentionLimits;
  status: RetentionStatus;
}

// TenantRetentionView is GET/PUT /v1/tenant/retention: the tenant's override
// (null = use the platform default, 0 = keep forever), the platform default
// it falls back to, the effective result and the accepted range.
export interface TenantRetentionView {
  tenantId: string;
  override: RetentionPolicy;
  default: RetentionPolicy;
  effective: RetentionPolicy;
  limits: RetentionLimits;
}

// ---- wire/rooms.go ----

// RoomSummary is one room of the caller's own room list
// (GET /v1/users/{id}/rooms?detail=1). Role is the caller's role in it.
export interface RoomSummary {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  syncMode: RoomSyncMode;
  role: RoomRole;
  memberCount: number;
  createdAtMs: number;
}

// RoomsReply is the caller's room list.
export interface RoomsReply {
  rooms: RoomSummary[];
}

// RoomDetail is GET /v1/rooms/{id} for a member (and the answer to a create
// or a PATCH). The caller's role is not part of it: it comes from the member
// list (RoomMembersReply), the one source a role change updates.
export interface RoomDetail {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  syncMode: RoomSyncMode;
  createdBy: string;
  createdAtMs: number;
  memberCount: number;
}

// RoomPreview is GET /v1/rooms/{id} for a non-member of a shared room: just
// enough for a join card. Preview is always true (a private room answers
// 404 to a non-member).
export interface RoomPreview {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  memberCount: number;
  preview: boolean;
}

// RoomMember is one membership of a room. AgentHost marks a platform
// agent's host: in the room only so its bridge drives that agent, never a
// person (clients keep it out of people lists).
export interface RoomMember {
  userId: string;
  role: RoomRole;
  agentHost: boolean;
}

// RoomMembersReply is GET /v1/rooms/{id}/members (members only).
export interface RoomMembersReply {
  members: RoomMember[];
}

// PlazaRoom is one room of the plaza (GET /v1/rooms?q=). A private room is
// Locked: only its name and description are shown, never who made it or
// how many are in it.
export interface PlazaRoom {
  roomId: string;
  name: string;
  description: string;
  visibility: RoomVisibility;
  locked: boolean;
  syncMode?: RoomSyncMode;
  createdBy?: string;
  createdAtMs?: number;
  memberCount?: number;
}

// PlazaReply is one page of the plaza: Total rooms match, this page starts
// at Offset and holds at most Limit.
export interface PlazaReply {
  rooms: PlazaRoom[];
  total: number;
  limit: number;
  offset: number;
}

// ChannelUnread is one channel's unread count.
export interface ChannelUnread {
  channelId: string;
  count: number;
}

// UnreadReply is GET /v1/rooms-unread?rooms= (at most MaxUnreadRooms):
// per room, the unread total (a room with none is absent) and the channels
// that have unread messages, default channel first.
export interface UnreadReply {
  unread: Record<string, number>;
  channels: Record<string, ChannelUnread[]>;
}

// ---- wire/schedules.go ----

// MaxChatTextBytes is the product cap on one chat message's text. realtime
// enforces it on every post; schedule and template validation use the same
// bound so a stored scheduled prompt always fits the post it becomes.
export const MaxChatTextBytes = 16384;

// Schedule recipient kinds: a people-only room message, a message
// addressed to one member's agent (the bridge serving that agent claims it,
// and enforces borrow authorization at drive time exactly as for a typed
// message), or a task in plain words the assist model carries out with the
// room's actions, as the schedule's owner (docs/prd/2026-10-15-app-
// identity-schedules-notify-ai.md §4).
export const ScheduleRecipientRoom = "room";
export const ScheduleRecipientAgent = "agent";
export const ScheduleRecipientAI = "ai";
// ScheduleRecipientNotice is a notice sent at set times, through the
// notification emitter (the one an app's notify uses): where it goes, its
// title and its body are the schedule's own, so a run needs no model to
// say what to do. With Compose the model only writes the body.
export const ScheduleRecipientNotice = "notice";

// Schedule recurrence kinds.
// RecurOnce runs once at AtMs.
export const RecurOnce = "once";
// RecurDaily runs every day at Time (HH:MM) in the schedule's timezone.
export const RecurDaily = "daily";
// RecurWeekly runs on Days (0=Sunday..6=Saturday) at Time.
export const RecurWeekly = "weekly";
// RecurCron runs on a five-field cron-lite expression
// ("minute hour day-of-month month day-of-week").
export const RecurCron = "cron";

// Schedule run outcomes recorded on the schedule (LastStatus).
export const ScheduleRunOK = "ok";
export const ScheduleRunError = "error";
export const ScheduleRunSkipped = "skipped";

// ScheduleRecipient addresses a scheduled message. Kind "room" drives no
// agent; kind "agent" carries the target agent's owner + provider (+ core
// when the owner exposes more than one).
export interface ScheduleRecipient {
  kind: ScheduleRecipientKind;
  ownerId?: string;
  provider?: string;
  core?: string;
  // For kind "notice": To is where it goes, as an app's notify says it
  // (AppNotifyRoom, a list of logins, or "group:<name>"); Title is its title
  // and URL an optional link on this deployment. The schedule's text is its
  // body, in which {date}, {week} and the other NoticeVars names stand for the
  // run's own values. With Compose the text is instead what the model is asked
  // to write the body from each run (the destination and title stay fixed).
  to?: unknown;
  title?: string;
  url?: string;
  compose?: boolean;
}

// ScheduleRecurrence is when a schedule fires. Only the fields of its Kind
// are meaningful: AtMs (once), Time (daily, weekly), Days (weekly), Cron
// (cron).
export interface ScheduleRecurrence {
  kind: RecurrenceKind;
  atMs?: number;
  time?: string;
  days?: number[];
  cron?: string;
}

// RoomSchedule is one scheduled prompt: Text posted into the room as
// CreatedBy, addressed to Recipient, whenever Recurrence fires in Timezone.
// NextRunAtMs is 0 when the schedule will not fire (paused, or a one-shot
// that already ran).
export interface RoomSchedule {
  scheduleId: string;
  tenantId: string;
  roomId: string;
  channelId?: string;
  createdBy: string;
  text: string;
  recipient: ScheduleRecipient;
  recurrence: ScheduleRecurrence;
  timezone: string;
  enabled: boolean;
  nextRunAtMs?: number;
  lastRunAtMs?: number;
  lastStatus?: ScheduleRunStatus;
  lastError?: string;
  // LastSummary is what an ai schedule's last run did, in a line.
  lastSummary?: string;
  // FailedRuns is how many runs in a row failed (0 after a run that
  // did not).
  failedRuns?: number;
  lastSeq?: number;
  runCount: number;
  createdAtMs: number;
  updatedAtMs: number;
}

// ScheduleRunRequest is realtime's call to the gateway to run an ai
// schedule's slot (POST /internal/v1/schedule-runs): the schedule as
// stored, the slot it runs (the idempotency of what it sends), and DryRun:
// read for real, send nothing, report what it would do.
export interface ScheduleRunRequest {
  schedule: RoomSchedule;
  slotMs: number;
  dryRun?: boolean;
}

// ScheduleRunReply is what an ai run did: its outcome (ScheduleRunStatus),
// its summary (the model's last words), an error a person reads, and the
// actions it took (or, dry, would take).
export interface ScheduleRunReply {
  status: ScheduleRunStatus;
  summary?: string;
  error?: string;
  actions: ScheduleAction[];
  // Seq is the last message the run posted (0: none).
  seq?: number;
}

// ScheduleAction is one action of a run: its name and what it did, in a
// line; DryRun when it was only described.
export interface ScheduleAction {
  name: string;
  detail: string;
  dryRun?: boolean;
}

// ScheduledMarker is set as payload.scheduled on a chat_message the scheduler
// posted, so clients can badge it. A typed message never carries it.
export interface ScheduledMarker {
  scheduleId: string;
}

// Room template visibility values: private is the author only, tenant is
// every member of the author's tenant.
export const TemplatePrivate = "private";
export const TemplateTenant = "tenant";

// TemplateAgent is a suggested agent of a template: a HINT only. After a
// room is created from the template the UI offers to invite the owner and
// to request that owner's borrow authorization; nothing is ever granted
// automatically.
export interface TemplateAgent {
  ownerId: string;
  provider: string;
  core?: string;
}

// TemplateSchedule is a schedule captured in a template. Channel is a channel
// NAME of the template (ids are per room); empty means the default channel.
// Instantiation creates it disabled, owned by the member who instantiated.
export interface TemplateSchedule {
  channel?: string;
  text: string;
  recipient: ScheduleRecipient;
  recurrence: ScheduleRecurrence;
  timezone: string;
}

// TemplateContentUse is a content component a template turns on in every
// room made from it: a room content use, pinned to Version or following the
// latest when empty.
export interface TemplateContentUse {
  componentId: string;
  version?: string;
}

// RoomTemplateBody is what a template sets up in a new room. A template's
// starters are its prompt packs' (PromptPacks become the new room's prompt
// pack uses); it has no starter list of its own.
export interface RoomTemplateBody {
  roomDescription?: string;
  channels: string[];
  promptPacks: TemplateContentUse[];
  suggestedAgents: TemplateAgent[];
  defaultMembers: string[];
  schedules: TemplateSchedule[];
}

// RoomTemplate is one template in the tenant's template library.
export interface RoomTemplate {
  templateId: string;
  tenantId: string;
  name: string;
  description?: string;
  visibility: TemplateVisibility;
  createdBy: string;
  body: RoomTemplateBody;
  useCount: number;
  createdAtMs: number;
  updatedAtMs: number;
}

// RoomTemplateInstance is the instantiate response: the new room and what
// the template set up in it. SuggestedAgents are returned for the UI's
// follow-up offers; no grant is created for any agent. PromptPacks are the
// component ids turned on in the room; FailedPromptPacks the template's
// packs the creator may not use, left out.
export interface RoomTemplateInstance {
  roomId: string;
  name: string;
  templateId: string;
  channels: string[];
  addedMembers: string[];
  failedMembers?: string[];
  schedules: string[];
  promptPacks: string[];
  failedPromptPacks?: string[];
  suggestedAgents: TemplateAgent[];
}

// ---- wire/search_reindex.go ----

// SearchReindexRequest is the body of POST /v1/platform/search/reindex
// (super-admin, served by realtime): continue the search reindex after
// Cursor ("" = from the start), processing at most MaxBatches batches
// (0 = the server default; the server also caps one call's wall time).
export interface SearchReindexRequest {
  cursor?: string;
  maxBatches?: number;
}

// SearchReindexResponse is one call's progress: the search backend, rows
// read and rows brought into the index in this call (mysql: search text
// filled for rows stored without it; opensearch: documents written), the
// cursor to pass to the next call, and whether the whole feed has been
// walked.
export interface SearchReindexResponse {
  backend: string;
  scanned: number;
  updated: number;
  cursor: string;
  done: boolean;
}

// SearchStatus is GET /v1/platform/search/status (super-admin, served by
// realtime): the search backend and its health as the answering replica
// sees it.
export interface SearchStatus {
  // Backend is "mysql" (the store's FULLTEXT index) or "opensearch".
  backend: string;
  // Index is the OpenSearch index name (opensearch only).
  index?: string;
  // Ready is false while the backend is unreachable or its index is
  // missing and cannot be created.
  ready: boolean;
  // Health is the index's cluster health (green, yellow, red; opensearch
  // only).
  health?: string;
  // Documents is the index's document count (opensearch only).
  documents?: number;
  // Error explains a not-ready backend.
  error?: string;
  // Updates is the answering replica's index update queue (opensearch
  // only: the store index needs none).
  updates?: SearchUpdateStats;
}

// SearchUpdateStats counts one replica's asynchronous index updates since
// it started (messages, not batches).
export interface SearchUpdateStats {
  queued: number;
  applied: number;
  failed: number;
  dropped: number;
}

// ---- wire/shares.go ----

// Who may open a share link (ShareView.Access): a signed-in member of the
// room's organization (the default), anyone who can sign in to this
// deployment whatever their organization, or anyone holding the link,
// without signing in. The last two are the creator's opt-in, each
// refused while the organization disallows it
// (store.Tenant.ShareAccessAllowed).
export const ShareAccessOrg = "org";
export const ShareAccessSignedIn = "signed_in";
export const ShareAccessAnyone = "anyone";

// ShareAccessModes is every access mode, narrowest reach first.
export const ShareAccessModes: readonly string[] = ["org", "signed_in", "anyone"];

// ShareCreateRequest is POST /v1/rooms/{roomId}/artifacts/{artifactId}/shares:
// Version 0 (or absent) follows the latest version; ExpiresInHours
// 1..2160 (default 168); Access defaults to ShareAccessOrg.
export interface ShareCreateRequest {
  version?: number;
  expiresInHours?: number;
  access?: ShareAccess;
}

// ShareCreated answers a link's create (201): the link and its token,
// shown this once (only its hash is stored). URL is the link to hand out,
// `<public origin>/s/<token>` (sharelink.URL): the room service leaves it
// empty and the gateway fills it in on the way out, so every link is
// spelled by one owner on the gateway's public origin
// (docs/prd/2026-10-13-short-share-links.md).
export interface ShareCreated {
  share: ShareView;
  token: string;
  url: string;
}

// ShareAccessUpdate is PATCH …/shares/{shareId}: the link's new access.
export interface ShareAccessUpdate {
  access: ShareAccess;
}

// ShareTicketRequest is POST /v1/share-tickets: the link's token, in the
// body so it never reaches an access log.
export interface ShareTicketRequest {
  token: string;
}

// ShareTicket answers a ticket mint: a signed credential of the signed-in
// member for one link, used in place of the link's token in
// /v1/public/shares/{…} (metadata, content, site, ~app).
export interface ShareTicket {
  ticket: string;
  expiresAtMs: number;
}

// The codes of a share route's refusal (httpx.ErrorBody code) the share
// page acts on.
// ShareSignInRequired: an org or signed_in link opened without signing
// in (401).
export const ShareSignInRequired = "share_sign_in_required";
// ShareOrgOnly: the signed-in caller is not a member of the link's
// organization (403).
export const ShareOrgOnly = "share_org_only";

// ShareView is one share link as the room service lists it.
export interface ShareView {
  shareId: string;
  artifactId: string;
  version: number; // 0 = follows the latest version
  createdBy: string;
  createdAtMs: number;
  expiresAtMs: number;
  revokedAtMs?: number;
  revokedBy?: string;
  viewCount: number;
  lastViewedAtMs?: number;
  // Access is who may open the link (ShareAccessModes).
  access: ShareAccess;
  // Active is the link's own state (not revoked, not expired); the
  // organization switch is reported by GET /v1/my/tenant-policy.
  active: boolean;
  // Copyable is set only for the link's creator, on an active link whose
  // token was stored sealed: GET …/shares/{shareId}/link answers it again
  // (docs/prd/2026-10-16-share-link-copy-again.md).
  copyable?: boolean;
}

// ShareLink answers GET /v1/rooms/{roomId}/artifacts/{artifactId}/shares/{shareId}/link:
// the link of its creator's active share. The room service answers Token;
// the gateway replaces it with URL on the way out, as for a link's create
// (ShareCreated), so the token itself never reaches the client.
export interface ShareLink {
  token?: string;
  url?: string;
}

// ShareResolveRequest is the gateway's internal POST
// /internal/v1/shares/resolve: a link's token (its secret is verified), or
// the share id of a share ticket the gateway signed.
export interface ShareResolveRequest {
  token?: string;
  shareId?: string;
}

// ShareViewCount is the gateway's internal POST /internal/v1/shares/view:
// one view of a link its caller was allowed to open.
export interface ShareViewCount {
  shareId: string;
}

// ShareResolution is the room service's answer to the gateway's internal
// POST /internal/v1/shares/resolve for a live link.
export interface ShareResolution {
  tenantId: string;
  // OrgName is the organization's display name (its id when it has
  // none), for the refusal of a caller outside it.
  orgName: string;
  roomId: string;
  share: ShareView;
  artifact: ShareArtifact;
  version: ShareVersion;
  sharedBy: ShareUser;
}

// ShareArtifact is the shared artifact's identity.
export interface ShareArtifact {
  artifactId: string;
  kind: string;
  title: string;
  fileName: string;
}

// ShareVersion is the resolved version (the latest one, resolved at call
// time, for a link that follows the latest).
export interface ShareVersion {
  version: number;
  storage: string;
  mimeType: string;
  sizeBytes: number;
  contentHash: string;
  blobKey?: string;
  content?: string; // inline versions only
  summary?: string;
  createdAtMs: number;
}

// ShareUser names who shared the link.
export interface ShareUser {
  userId: string;
  // DisplayName is what an outsider sees as "shared by": the user's
  // display name with the default applied (store.DisplayName — the local
  // part of the id when none is set; ids are usually e-mail addresses and
  // the full address is not published).
  displayName: string;
}

// ---- wire/team.go ----

// Message task status values.
export const TaskOpen = "open";
export const TaskDone = "done";

// EventTaskUpdated is the transient room event published when a message task
// is marked, toggled, or unmarked. It carries TaskUpdatedPayload and is never
// persisted (realtime's persist() allowlist stores only chat_message and
// agent_messages).
export const EventTaskUpdated = "task_updated";

// MessageTask marks one persisted room message (by its room sequence) as a
// task. Title and MessageAuthor are snapshots taken when the task was marked.
export interface MessageTask {
  roomId: string;
  channelId?: string;
  seq: number;
  status: TaskStatus;
  title: string;
  messageAuthor?: string;
  createdBy: string;
  createdAtMs: number;
  doneBy?: string;
  doneAtMs?: number;
}

// TaskUpdatedPayload is the payload of an EventTaskUpdated event: the task's
// new state, or Removed with only Seq set when the task was unmarked.
export interface TaskUpdatedPayload {
  seq: number;
  task?: MessageTask;
  removed?: boolean;
}

// Search result kinds.
export const SearchMessage = "message";
export const SearchArtifact = "artifact";
// SearchPrompt is a prompt of a prompt pack the member can see (their
// own, shared with them, their organization's, the platform's).
export const SearchPrompt = "prompt";

// SearchResult is one global-search hit. Snippet is plain text (the client
// highlights the query); RoomID/RoomName/Seq/ChannelID locate a message hit,
// ArtifactID an artifact hit.
export interface SearchResult {
  kind: SearchResultKind;
  roomId?: string;
  roomName?: string;
  channelId?: string;
  // ChannelKind is "people" when the hit is in the room's people chat.
  channelKind?: string;
  seq?: number;
  artifactId?: string;
  // ArtifactKind / MimeType / FileName type an artifact hit (file icon,
  // viewer choice) without a second fetch.
  artifactKind?: string;
  mimeType?: string;
  fileName?: string;
  title?: string;
  // ComponentID / PromptID name a prompt hit's pack and prompt.
  componentId?: string;
  promptId?: string;
  snippet: string;
  author?: string;
  atMs: number;
}

// SearchResponse is the GET /v1/search reply. NextBefore, when non-zero, is
// the `before` cursor for the next (older) page of message hits.
export interface SearchResponse {
  results: SearchResult[];
  nextBefore?: number;
}

// ---- wire/team_agents.go ----

// Team dashboard ranges.
export const TeamRangeToday = "today";
export const TeamRange7d = "7d";

// TeamJob is one agent job as the dashboard shows it (no prompt text).
export interface TeamJob {
  jobId: string;
  roomId: string;
  roomName?: string;
  channelId?: string;
  requester: string;
  status: AgentJobStatus;
  failureReason?: AgentJobFailureReason;
  createdAtMs: number;
  startedAtMs?: number;
  finishedAtMs?: number;
}

// TeamAgentUsage is the reported reply metrics summed over the range. CostUsd
// is present only when at least one reply reported a cost. Shared marks usage
// that could not be split between two of the owner's cores exposing the same
// provider (replies carry the provider, not the core): each such row shows
// the provider's combined total.
export interface TeamAgentUsage {
  reportedTurns: number;
  inputTokens: number;
  outputTokens: number;
  costUsd?: number;
  shared?: boolean;
}

// TeamAgent is one member's agent on the dashboard. Turns counts jobs in the
// range that ended replied; FailedTurns those that ended failed/timed out;
// BorrowedRuns the replied jobs requested by someone other than the owner.
export interface TeamAgent {
  owner: string;
  core: string;
  provider: string;
  targetId?: string;
  online: boolean;
  lastSeenAtMs?: number;
  currentJob?: TeamJob;
  lastJob?: TeamJob;
  turns: number;
  failedTurns: number;
  borrowedRuns: number;
  usage?: TeamAgentUsage;
}

// TeamAgentsReply is GET /v1/team/agents (scope "self") and
// GET /v1/tenant/team/agents (scope "tenant").
export interface TeamAgentsReply {
  scope: string;
  range: TeamRange;
  sinceMs: number;
  agents: TeamAgent[];
}

// Borrow usage report grouping values.
export const UsageGroupDay = "day";
export const UsageGroupMonth = "month";

// Borrow usage report perspectives.
export const UsageAsOwner = "owner";
export const UsageAsBorrower = "borrower";
export const UsageAsTenant = "tenant";

// BorrowUsageRow is one (period, owner, borrower, provider, room) bucket of
// recorded borrow turns. Cost sums the turns that reported one; it is absent
// when none did. InputTokens / OutputTokens likewise sum the turns that
// reported token usage and are absent when none did.
export interface BorrowUsageRow {
  period: string;
  owner: string;
  borrower: string;
  provider: string;
  roomId: string;
  runs: number;
  cost?: number;
  inputTokens?: number;
  outputTokens?: number;
}

// BorrowUsageReport is GET /v1/borrow/usage-report (and the tenant variant).
// Truncated is set when the scan hit its row cap.
export interface BorrowUsageReport {
  as: UsageAs;
  groupBy: UsageGroupBy;
  fromMs: number;
  toMs: number;
  rows: BorrowUsageRow[];
  totalRuns: number;
  totalCost?: number;
  // TotalInputTokens / TotalOutputTokens are absent when no turn in the
  // report carried token usage.
  totalInputTokens?: number;
  totalOutputTokens?: number;
  truncated?: boolean;
}

// Quota request statuses.
export const QuotaPending = "pending";
export const QuotaApproved = "approved";
export const QuotaDeclined = "declined";

// Borrow request kinds (QuotaRequest.Kind; store.QuotaRequestKind): more
// runs on a live authorization, or access to borrow at all — recorded when
// a borrow was refused because the owner had authorized none; approving it
// authorizes the agent in the room.
export const QuotaKindRuns = "quota";
export const QuotaKindAccess = "access";

// QuotaRequest is one borrower's request for more runs on an owner's room
// authorization of Provider (the grant discriminator: "<core>:<provider>" or a
// bare provider), or (Kind access) for an authorization to borrow it.
export interface QuotaRequest {
  requestId: string;
  roomId: string;
  owner: string;
  requester: string;
  provider: string;
  kind: QuotaRequestKind;
  requestedRuns?: number;
  note?: string;
  status: QuotaRequestStatus;
  grantedRuns?: number;
  createdAtMs: number;
  decidedAtMs?: number;
}

// CreateQuotaRequestInput is the POST /v1/borrow/quota-requests body. The
// requester is always the authenticated caller, never a body field.
export interface CreateQuotaRequestInput {
  roomId: string;
  owner: string;
  provider: string;
  requestedRuns?: number;
  note: string;
}

// ApproveQuotaRequestInput is the optional approve body: Runs overrides the
// requested amount (the owner may grant fewer or more).
export interface ApproveQuotaRequestInput {
  runs?: number;
}

// ---- wire/teams.go ----

// MaxTeamFailures is how many member tasks of one request may fail before
// the room tools refuse the lead further dispatches. A protocol safety
// constant beside MaxDispatchDepth and MaxDispatchFanOut: it bounds what a
// failing team spends on one person's request, the same everywhere.
export const MaxTeamFailures = 3;

// ContentTeam is a team expert's roster. In a listing or detail it is the
// manifest's; in ContentEffective each member carries its resolution.
export interface ContentTeam {
  // Lead is the lead's role title.
  lead: string;
  members: ContentTeamMember[];
}

// ContentTeamMember is one role of a team.
export interface ContentTeamMember {
  role: string;
  expert: string;
  defaultAgent: string;
  description?: string;
  // Resolved is the member expert the requester may use (effective
  // only); Missing says why there is none.
  resolved?: ContentTeamExpert;
  missing?: string;
}

// ContentTeamExpert is a team member's expert as it resolved.
export interface ContentTeamExpert {
  componentId: string;
  name: string;
  displayName?: string;
  description?: string;
  version: string;
}

// PlanAgent names one agent of a room: owner, core and provider, plus its
// handle as the room tools name it ("owner/provider", "owner/core/provider"
// where an owner exposes the provider on two cores).
export interface PlanAgent {
  ownerId: string;
  core?: string;
  provider: string;
  handle?: string;
  // Platform marks a platform agent (served by a host member).
  platform?: boolean;
}

// TeamPlanRole is one role the plan staffs: its name and default agent.
export interface TeamPlanRole {
  role: string;
  defaultAgent: string;
}

// TeamPlanRequest is POST /v1/rooms/{roomId}/team-plan. Lead is the agent
// the requester picked (the composer); with ?job= (the lead's bridge) the
// lead and the requester are the job's and Lead is ignored.
export interface TeamPlanRequest {
  lead?: PlanAgent;
  members: TeamPlanRole[];
}

// AgentCostSample is an agent's recent reported cost: how many of its last
// finished runs reported one, and their average (absent when none did).
export interface AgentCostSample {
  runs: number;
  avgCostUsd?: number;
}

// TeamPlanEntry is one staffed (or unstaffed) seat of the plan.
export interface TeamPlanEntry {
  // Role is the role's name ("" for the lead).
  role?: string;
  defaultAgent?: string;
  // Agent is the agent that takes the seat; absent when none can, and
  // Reason says why.
  agent?: PlanAgent;
  online: boolean;
  reason?: string;
  cost?: AgentCostSample;
}

// TeamCostEstimate is the plan's pre-flight estimate of one team request:
// the lead plus every staffed role once, from each agent's average
// reported cost. CostUsd is absent when no seat has data; Unknown names the
// seats ("lead" or a role) without data, which the sum leaves out.
export interface TeamCostEstimate {
  costUsd?: number;
  runs: number;
  unknown?: string[];
}

// TeamPlanReply answers POST /v1/rooms/{roomId}/team-plan.
export interface TeamPlanReply {
  lead: TeamPlanEntry;
  roles: TeamPlanEntry[];
  estimate: TeamCostEstimate;
}

// ---- wire/tenant_policy.go ----

// TenantPolicy is GET /v1/my/tenant-policy: the organization's name and the
// org-admin policy a member's surfaces follow. The owner's bridge reads
// RequireSandboxForBorrow (borrowed drives must run sandboxed); the web's
// share dialog offers the link access modes in ShareAccess, and publishing
// to the organization says whether an admin approves it.
export interface TenantPolicy {
  tenantId: string;
  name: string;
  requireSandboxForBorrow: boolean;
  // ShareAccess is the link access modes the organization allows, in
  // ShareAccessModes order: store.Tenant.ShareAccessAllowed's answer for
  // each, so no client re-decides it.
  shareAccess: ShareAccess[];
  publishApproval: PublishApproval;
}

// ---- wire/turn_usage.go ----

// TurnUsage is the usage one agent reply reports in its free-form metrics map
// (the reply payload's "metrics": model, reported, inputTokens, outputTokens,
// costUsd). It is the ONE reading of that map shared by every consumer — the
// bridge's borrow record and the team dashboard's memory aggregation — so a
// reply counts the same everywhere.
//
// Reported is false when the map is empty or the core marked it
// reported=false (tokens and cost unknown); then the token counts are zero and
// must not be presented as a measured zero. CostUsd is nil unless the reply
// carried a numeric costUsd. Model is read whenever present.
export interface TurnUsage {
  Model: string;
  Reported: boolean;
  InputTokens: number;
  OutputTokens: number;
  CostUsd: number | null;
}

// ---- wire/updates.go ----

// Update channels a desktop build can follow.
export const UpdateChannelStable = "stable";
export const UpdateChannelInternal = "internal";

// UpdateTargets are the Tauri updater targets the gateway serves. They are
// the updater's own platform identifiers (a protocol constant of the Tauri
// updater, not deployment data).
export const UpdateTargets: readonly string[] = ["darwin-aarch64", "darwin-x86_64", "windows-x86_64"];

// UpdatePolicy is the operator-controlled desktop update policy.
export interface UpdatePolicy {
  enabled: boolean;
  channel: string;
  autoCheck: boolean;
  checkIntervalHours: number;
  autoInstall: boolean;
  minSupportedVersion: string;
}

// UpdatePlatform is one target's signed updater artifact.
export interface UpdatePlatform {
  url: string;
  signature: string;
}

// UpdateRelease is the release the updater currently offers. Every target
// shares its single version.
export interface UpdateRelease {
  version: string;
  notes: string;
  pubDate: string;
  platforms: Record<string, UpdatePlatform>;
}

// UpdateConfig is the full super-admin update configuration.
export interface UpdateConfig {
  policy: UpdatePolicy;
  release: UpdateRelease;
}

// ReleaseFile is one downloadable artifact for a version/platform.
export interface ReleaseFile {
  platform: string;
  arch: string;
  target?: string;
  name: string;
  url: string;
  sha256?: string;
  size?: number;
}

// ReleaseEntry is one published version of bnbloc. Notes is markdown so the
// changelog can grow structure without a schema change.
export interface ReleaseEntry {
  version: string;
  channel: string;
  releaseDate: string;
  notes: string;
  files: ReleaseFile[];
  createdAtMs?: number;
  createdBy?: string;
}

// ReleaseHubMeta is the instance-wide project intro shown above the history.
export interface ReleaseHubMeta {
  name: string;
  tagline: string;
  intro: string;
}

// ReleaseHub is the release hub payload: intro + history, newest first.
export interface ReleaseHub {
  project: ReleaseHubMeta;
  releases: ReleaseEntry[];
}

// ---- wire/versions.go ----

// ServiceVersion is one running service instance's build identity, served
// by every service at GET /version (internal/obs) and aggregated by the
// gateway at GET /v1/platform/versions.
export interface ServiceVersion {
  // Service is the process name (bnbloc-gateway, bnbloc-room, ...).
  service: string;
  // Commit is the source commit the binary was built from ("" = unknown:
  // built without CI_COMMIT_SHA outside a git checkout).
  commit: string;
  // BuiltAt is the build time (RFC 3339, UTC), "" when not stamped.
  builtAt?: string;
  // Instance is the host name of the answering process (the pod name
  // under Kubernetes), so replicas behind one Service DNS name differ.
  instance: string;
}

// WebBundleVersion is the build identity of the web bundle a gateway embeds.
export interface WebBundleVersion {
  version: string;
  commit: string;
}

// UnreachableService is a service whose /version could not be read.
export interface UnreachableService {
  service: string;
  error: string;
}

// DeploymentVersions is GET /v1/platform/versions (super-admin): every
// reachable instance of every service the gateway addresses, plus the
// gateway's own and its embedded web bundle. Consistent is false when known
// commits differ, a service is unreachable, or the web identity is missing
// (Problems says why). A component built without a commit stamp cannot be
// compared: it is a Warning (unverifiable), not skew.
export interface DeploymentVersions {
  services: ServiceVersion[];
  web?: WebBundleVersion;
  unreachable?: UnreachableService[];
  consistent: boolean;
  problems?: string[];
  warnings?: string[];
}

// ---- wire/webpush.go ----

// WebPushPublicKey answers GET /v1/push/vapid-public-key (404 when the
// deployment has no VAPID key pair: the channel is disabled).
export interface WebPushPublicKey {
  // PublicKey is the VAPID application server key, base64url (unpadded)
  // of the uncompressed P-256 point, as PushManager.subscribe expects it.
  publicKey: string;
}

// WebPushSubscriptionKeys are a PushSubscription's encryption keys
// (PushSubscription.toJSON().keys), base64url.
export interface WebPushSubscriptionKeys {
  p256dh: string;
  auth: string;
}

// WebPushSubscriptionInput is the POST /v1/my/push-subscriptions body (the
// browser's PushSubscription.toJSON()) and, with only Endpoint, the DELETE
// body.
export interface WebPushSubscriptionInput {
  endpoint: string;
  keys: WebPushSubscriptionKeys;
}

// WebPushMessage is the decrypted push message the service worker receives.
export interface WebPushMessage {
  id: string;
  type: string;
  roomId?: string;
  title: string;
  body: string;
  // URL is the absolute deep link ("" without a public URL); Path is its
  // hash route ("#/room/<id>?seq=<n>"), which the worker opens on its own
  // origin when URL is empty.
  url?: string;
  path: string;
}

// ---- wire/wire.go ----

// ReportSessionStateInput is the body of the session-state ingest endpoint.
// It mirrors the open-source agentsessionstore ReportSessionStateInput.
export interface ReportSessionStateInput {
  workspaceId: string;
  agentSessionId: string;
  providerSessionId?: string;
  ownerUserId: string;
  // Provider and Core name WHICH agent of the owner this state is for, so
  // a room with several agents shows one working indicator per agent
  // (the web keys it by agentIdentity: owner, core, provider).
  provider?: string;
  core?: string;
  state: unknown;
  messageVersion: number;
  occurredAtUnixMs: number;
}

// ReportSessionStateReply acknowledges a persisted session-state report.
export interface ReportSessionStateReply {
  syncCursor: number;
}

// Message is one canonical agent activity message.
export interface Message {
  seq: number;
  payload: unknown;
  createdAtUnixMs: number;
}

// ReportMessagesInput is the body of the messages ingest endpoint.
export interface ReportMessagesInput {
  workspaceId: string;
  agentSessionId: string;
  channelId?: string;
  messages: Message[];
  cursor: number;
}

// ReportMessagesReply returns the next durable message cursor.
export interface ReportMessagesReply {
  nextCursor: number;
}

// RosterAgent is one agent a member's bridge advertises as reachable in a room.
// The room agent roster is the union of these across members, letting the
// composer picker offer real drivable agents without the gateway reaching any
// user's machine (remote-safe). Core is empty for a borrowed/coreless entry.
export interface RosterAgent {
  ownerUserId: string;
  core?: string;
  provider: string;
  // Sandboxed: borrowed drives of this agent run in its owner's agent
  // sandbox (advertised by the owner's bridge).
  sandboxed?: boolean;
}

// Event is a schema-first business event or presence delta fanned out over the
// realtime lane. Sequence is per-connection; older deliveries are ignored.
export interface Event {
  sequence: number;
  roomId: string;
  // ChannelID routes the event to one channel of the room's message stream.
  // "" is room-wide (presence, roster, and other non-channel kinds): every
  // subscriber receives it regardless of the channel they follow.
  channelId?: string;
  kind: string;
  payload: unknown;
  atUnixMs: number;
}

// Access-revocation event kinds. bnbloc-room publishes them (transient, never
// persisted) when access to a room ends, and realtime closes the affected live
// streams after delivering them, so a removed member or a deleted room stops
// receiving events immediately instead of at the next reconnect.
// EventMemberRemoved carries MemberRemovedPayload; the removed member's
// streams in the room close.
export const EventMemberRemoved = "member_removed";
// EventRoomDeleted carries no payload; every stream in the room closes.
export const EventRoomDeleted = "room_deleted";

// MemberRemovedPayload is the payload of an EventMemberRemoved event.
export interface MemberRemovedPayload {
  userId: string;
}

// EventMemberJoined (MemberJoinedPayload) is published by bnbloc-room,
// transient, when a person becomes a member of a room (added, joined a
// shared room, redeemed an invite, a template's default member). Realtime's
// publish tap gives the new member the room's standing content shares
// (internal/contentshare); clients may refresh their member lists on it.
export const EventMemberJoined = "member_joined";

// MemberJoinedPayload is the payload of an EventMemberJoined event.
export interface MemberJoinedPayload {
  userId: string;
}

// Job notices. A synthetic assistant row about a job (a refused borrow, a
// failed or swept turn) is reported under the job's OWN activity session,
// never a real agent session: activity dedupes replies per
// (room, agentSessionId) by seq, so a notice in a real session would move its
// cursor and swallow later replies. Each job's notice session holds exactly
// one notice at JobNoticeSeq, so a retried or duplicate notice is a replay.
// The bridge and activity's job sweeper both use these, so their notices for
// one job share one namespace.
export const JobNoticeSeq = 1;

// ---- wire/works.go ----

// A work's category (component.json "category"), the gallery's tabs. A
// work names one of these or none; any other value is refused
// (contentpkg's work kind).
export const WorkCategoryOffice = "office";
export const WorkCategoryData = "data";
export const WorkCategoryProductivity = "productivity";
export const WorkCategoryContent = "content";
export const WorkCategoryLearning = "learning";
export const WorkCategoryEngineering = "engineering";
export const WorkCategoryFinance = "finance";
export const WorkCategoryLife = "life";
export const WorkCategoryOther = "other";

// WorkCategories lists the categories in the gallery's tab order.
export const WorkCategories: readonly string[] = ["office", "data", "productivity", "content", "learning", "engineering", "finance", "life", "other"];

// A work's type (component.json "type"): what the deliverable it
// snapshots is. It is derived from the deliverable (contentpkg.WorkTypeOf,
// the one rule), never typed by hand: an app is a site that loads the app
// SDK (store.Artifact.IsApp), a document is markdown, PDF, text or an
// office document.
export const WorkTypeApp = "app";
export const WorkTypeSite = "site";
export const WorkTypeImage = "image";
export const WorkTypeVideo = "video";
export const WorkTypeAudio = "audio";
export const WorkTypeDocument = "document";
export const WorkTypeSlides = "slides";
export const WorkTypeTable = "table";
export const WorkTypeOther = "other";

// WorkTypes lists the types in the gallery's filter order.
export const WorkTypes: readonly string[] = ["app", "image", "video", "audio", "document", "slides", "table", "site", "other"];

// Whether a member's publish to the organization waits for an org admin
// (the tenant settings' publishApproval; app gallery PRD §11). Required is
// the default; with none a publish takes effect at once, still audited,
// and admins can still unpublish, restore or remove it. It covers every
// content kind; contentshare.NeedsApproval is its one reader.
export const PublishApprovalRequired = "required";
export const PublishApprovalNone = "none";

// WorkPublishRequest is POST /v1/rooms/{roomId}/artifacts/{artifactId}/publish-work:
// snapshot the deliverable's current version (a site's files, or the one
// file, never its data) as a work component of the caller's. Without
// ComponentID it creates one named Name; with it, the snapshot is the next
// version of that work of the caller's. DisplayName defaults to the
// deliverable's title. The recipe is captured from the producing job
// (WorkRecipeCapture): Recipe overrides it (its references are a subset
// of the captured ones, named by attachmentId), RecipePrompt replaces only
// its request text (the request that produced the version was not one to
// make it: "publish it", a copy), and IncludeRecipe false publishes none.
export interface WorkPublishRequest {
  componentId?: string;
  name?: string;
  displayName?: string;
  description?: string;
  category?: WorkCategory;
  tags?: string[];
  recipe?: WorkRecipe;
  recipePrompt?: string;
  includeRecipe?: boolean;
}

// WorkRecipe is how a work was made (works PRD §3): the request that
// produced the deliverable version, the expert, skill packs and prompt
// packs the turn used, the files the request attached (stored in the
// work's bundle under references/) and the agent. It is captured from the
// producing job when the work is published, shown to the author first,
// and what "Make similar" starts from. Agent is informational only.
export interface WorkRecipe {
  prompt?: string;
  expert?: WorkRecipePart;
  skills?: WorkRecipePart[];
  prompts?: WorkRecipePart[];
  references?: WorkReference[];
  agent?: WorkRecipeAgent;
}

// WorkRecipePart is a content component a recipe used: an expert, a skill
// pack or a prompt pack, at the version the turn used.
export interface WorkRecipePart {
  id: string;
  name: string;
  displayName?: string;
  version?: string;
}

// WorkReference is one input file of a recipe. In a work's manifest File
// is its path in the bundle (references/<name>); while a recipe is only
// captured (before publishing) AttachmentID names the request's
// attachment it comes from and File is empty.
export interface WorkReference {
  file?: string;
  attachmentId?: string;
  name: string;
  contentType: string;
  sizeBytes: number;
}

// WorkRecipeAgent is the agent that produced the work (informational:
// "Make similar" runs on the member's own choice).
export interface WorkRecipeAgent {
  core?: string;
  provider: string;
}

// WorkRecipeCapture answers GET /v1/rooms/{roomId}/artifacts/{artifactId}/recipe:
// the recipe a publish of the deliverable's current version (Version)
// captures; Recipe is absent when no producing job is found (an uploaded
// file). Skipped names the request's attachments left out (over the
// reference caps, wire.MaxWorkReferences and MaxWorkReferenceBytes).
export interface WorkRecipeCapture {
  version: number;
  recipe?: WorkRecipe;
  skipped?: string[];
}

// AppUseRequest is POST /v1/content-components/{id}/use-app: copy an app
// work (Version, default its latest) into a room the caller owns (RoomID)
// or into a new room (NewRoom).
export interface AppUseRequest {
  version?: string;
  roomId?: string;
  newRoom?: WorkNewRoom;
}

// WorkNewRoom names the room "Use this app" or "Make similar" creates
// (default: the work's display name).
export interface WorkNewRoom {
  name?: string;
}

// AppDemo answers POST /v1/content-components/{id}/versions/{v}/demo:
// where an app version's demo runs. SiteURL is a site URL (on the sites
// origin when the deployment has one) whose ~app/sdk.js is the SDK in demo
// mode: its data lives in the page's memory only, and no app data call
// is answered under it.
export interface AppDemo {
  siteUrl: string;
  expiresAtMs: number;
}

// AppUseReply answers "Use this app": the new site deliverable, which
// starts with an empty data space of its own.
export interface AppUseReply {
  roomId: string;
  artifactId: string;
  version: number;
  createdRoom?: boolean;
  // From attributes the copy: "<name>@<version>".
  from: string;
}

// MakeSimilarRequest is POST /v1/content-components/{id}/make-similar:
// start from a work's recipe (Version, default its latest) in a room the
// caller may post in (RoomID) or in a new room (NewRoom).
export interface MakeSimilarRequest {
  version?: string;
  roomId?: string;
  newRoom?: WorkNewRoom;
}

// MakeSimilarDraft answers "Make similar": the composer draft the room
// opens with. Text is the recipe's prompt, Expert the recipe's expert when
// the caller may use it, AttachmentIDs the recipe's reference files (the
// work itself when the recipe is empty) copied into the room as the
// caller's attachments (Attachments their metadata, for the composer's
// chips). Enabled names the skill packs and prompt packs turned on in the
// room, Skipped what was left out (not visible to the caller, not theirs
// to turn on in that room, or not attachable).
export interface MakeSimilarDraft {
  roomId: string;
  createdRoom?: boolean;
  text: string;
  expert?: WorkRecipePart;
  attachmentIds: string[];
  attachments: ChatAttachment[];
  enabled?: string[];
  skipped?: string[];
}

